programs.sol:
"""A sparse approximation to a number-linked joining/counting feature.

Multiplication and size expressions, dimensional D, and selected Chinese noun
classifiers receive negative values. Short hyphenated suffixes after numbers
receive positive values. Chinese classifier meanings come from CC-CEDICT, not
token IDs. Compound words weaken the classifier reading. Other text is mostly
zero; the last 1,000 characters provide causal context, reset for each document.
"""
import re
from functools import lru_cache
import cedict
import inflect

READS = ()
NUMERALS = set('零〇一二三四五六七八九十百千万萬亿億两兩几幾数數半余餘多')
DETERMINERS = set('这這那哪每各某该該首另此')
_engine = inflect.engine()
NUMBER_WORDS = {
    word for n in (*range(1, 20), *range(20, 100, 10), 100, 1000, 10**6, 10**9)
    for word in _engine.number_to_words(n).split()
}
DIMENSIONS = re.compile(
    r'\b(matrix|matrices|grids?|arrays?|squares?|rectangles?|cubes?|pixels?|'
    r'resolution|size|dimensions?|images?|screens?|sheets?|wood|dish|boards?|'
    r'chess|width|height|length|buffer)\b', re.I)
UNITS = re.compile(
    r'\b(?:\d+|[A-Za-z])\s*(?:mm|cm|m|ft|inches|inch|feet|foot|'
    r'meters?|metres?|centimeters?|centimetres?)\s*$', re.I)
# Meanings of the noun-classifier senses covered by the weaker counting rule.
COUNTED_KINDS = ('sets', 'birds', 'books', 'flat objects', 'large immovable objects',
                 'locations', 'gifts', 'rods', 'military generals', 'trees',
                 'houses', 'skill')

@lru_cache(None)
def counter_kind(ch):
    meanings = tuple(g.lower() for g in cedict.glosses(ch))
    if any(g.startswith(('classifier for families', 'classifier for rooms'))
           for g in meanings):
        return 'household'
    if any(g.startswith('classifier for ' + kind)
           for g in meanings for kind in COUNTED_KINDS):
        return 'noun'
    if any(g.startswith('(classifier) sum of money') for g in meanings):
        return 'noun'
    return ''


def predict(previous, token):
    w, left = token.strip(), previous.rstrip()
    if not w:
        return 0.0
    digit = bool(left and left[-1].isdigit())
    variable = bool(re.search(r'(?:^|[^\w])[A-Za-z]$', left))
    topic = bool(DIMENSIONS.search(previous[-200:]))
    if w == 'x':
        value = 0.065 - 0.073 * variable
        if digit:
            value -= 0.631 if re.search(r'(?:^|\D)0$', left) else 0.627
            if re.search(r'\b(?:a|an|the|each|every)\s+\d+$', left, re.I):
                value -= 5.444
            if re.search(r'\b(?:size|of|as|into|is)\s*\(?\d+$', left, re.I):
                value -= 1.717
            gap = previous[len(left):] + token[:len(token)-len(token.lstrip())]
            if '\n' in gap:
                value += 0.708
        if topic and (digit or variable):
            value -= 2.002
        return value - 1.468 * bool(UNITS.search(left))
    if w in ('X', '×'):
        return 0.014 - (digit or variable) * (0.643 + 1.619 * topic)
    if w == '*':
        return -0.050 * digit
    if w == 'times' and left.endswith('\\'):
        return -0.573 - 1.780 * topic
    if w.lower() == 'by':
        return -0.397 * digit - 0.571 * variable - 1.998 * bool(UNITS.search(left))
    if w in ('D', 'd'):
        return (-0.719 if w == 'D' else -0.068) * digit
    if re.match(r'^-[A-Za-z]', w):
        preceding_word = re.search(r'([A-Za-z]+)$', left)
        number_word = preceding_word and preceding_word.group().lower() in NUMBER_WORDS
        numberlike = digit or bool(left and left[-1] in NUMERALS) or number_word
        rest = w[1:]
        value = 0.0
        if len(rest) <= 4:
            if numberlike:
                value = 0.085 + 0.494 * (len(rest) == 1)
            elif previous[-1:].isalpha():
                value = 0.022
        if numberlike and rest.lower() in ('star', 'time'):
            value -= 1.222
        return value
    if w == '公' and digit:  # Chinese metric-unit prefix
        return 2.190
    if w == '年' and digit:
        return -0.183
    if w == '%-' and digit:
        return -1.814
    if w[0].isascii():
        return 0.0
    # A numeral/determiner and its classifier may share a token.
    body, merged = w, False
    active = bool(left and (digit or left[-1] in NUMERALS | DETERMINERS))
    for i in range(min(5, len(w)-1)):
        if w[i].isdigit() or w[i] in NUMERALS | DETERMINERS:
            j = i + 1
            while j < len(w) and (w[j].isdigit() or w[j] in NUMERALS):
                j += 1
            if j < len(w) and counter_kind(w[j]):
                body, merged, active = w[j:], True, True
                break
    kind = counter_kind(body[0])
    if not active or not kind:
        return 0.0
    value = -6.021 + 1.417 * merged if kind == 'household' else -2.386 + 1.119 * merged
    return value * (0.3 if len(body) > 1 else 1.0)


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(previous, token)
    return (doc, (previous + token)[-1000:]), float(value)

programs.haiku:
"""Draft 7: clause- and list-joiners.

A conjunction ('and', 'or', 'und', '&&', ...) or a comma is negative when it follows a
predicate: a comma, an adjective or participle (ending -ed, -ive, -ble, -ous, -ful, -ly), or a
copula clause ('was long and', 'is small enough and'). Those joiners are strongest when they
link two clauses or predicates. After plain nouns they are close to zero. Question marks are
mildly negative."""
import re

READS = ()

CONJ = {" and", "and", " or", " und", " &&", " ||", " e", " y", " et", " but"}
COMMAS = {",", "，", ",\n\n", "、"}
PREDICATE = re.compile(r"[A-Za-z]+(ed|ive|ble|ous|ful|ly)")
WORD = re.compile(r"[A-Za-z]+")
COPULA = {"is", "was", "were", "are", "be", "been", "being", "become", "becomes", "became",
          "looks", "look", "seems", "seemed", "remains", "remained", "stayed", "got", "felt", "grew"}
BREAK = {",", ".", "，", "。", ";", ":", "?", "!"}


def _copula_clause(strings, window=8):
    for s in reversed(strings[-window - 1:-1]):
        w = s.strip().lower()
        if w in COPULA:
            return True
        if w in BREAK or "\n" in s:
            return False
    return False


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1]
    prev = strings[-2].strip() if len(strings) > 1 else ""
    if len(strings) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    if tok in CONJ:
        if prev in {",", "，"}:
            value = -0.85
        elif PREDICATE.fullmatch(prev):
            value = -1.25
        elif _copula_clause(strings):
            value = -0.6
        elif WORD.fullmatch(prev):
            value = -0.1
        else:
            value = -0.5
    elif tok in COMMAS:
        if PREDICATE.fullmatch(prev):
            value = -0.55
        elif WORD.fullmatch(prev):
            value = -0.12
        else:
            value = -0.3
    elif tok == "?":
        value = -0.27
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Three sparse, negative lexical responses, not a general language detector.

Japanese: isolated sa (さ, サ) and the abstract-quality ending しさ.
Sa is stronger after a vowel kana and weaker after a non-Japanese boundary.
Chinese: the tide character 潮 and its wave/current compounds; also 市,
especially when it completes a market expression rather than a city name.
Dictionary glosses identify market expressions. Other tokens predict zero.
"""
from functools import lru_cache
import cedict
import regex

READS = ()
VOWEL_KANA = frozenset('あいうえおアイウエオ')
# The short names of the Shanghai and Shenzhen stock exchanges.
EXCHANGE_PREFIXES = frozenset('沪滬深')


@lru_cache(maxsize=2048)
def gloss(word):
    return '; '.join(cedict.glosses(word)).lower()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    last = previous[-1:]
    value = 0.0

    if text in ('さ', 'サ'):
        value = -5.2 if text == 'さ' else -1.3
        if not regex.search(r'[\p{Han}\p{Hiragana}\p{Katakana}]$', previous):
            value *= 0.55
        elif last in VOWEL_KANA:
            value -= 2.5
    elif text == 'しさ':
        value = -3.0
    elif text == '潮':
        value = -6.0
    elif '潮' in text:
        meaning = gloss(text)
        if 'wave' in meaning or 'current' in meaning:
            value = -3.8
    elif text == '市':
        meaning = gloss(last + text) if last else ''
        value = -0.6
        if last in EXCHANGE_PREFIXES:
            value = -7.5
        elif 'market' in meaning or 'bazaar' in meaning:
            value = -4.0
            if any(phrase in meaning for phrase in (
                    'night market', 'foreign exchange', 'close the market')):
                value = -7.5

    return None, value

programs.haiku:
"""layers.1.mlp.down_proj:4357: a word detector that goes negative on a few words.

The component is near zero almost everywhere. It goes negative on a small set of
words, grouped by meaning, with the typical activation for each word:

- the kana さ and its katakana twin サ, and the words しさ and さま that contain them:
  さ is about -5 (the strongest), サ about -1.3.
- 'tide / wave' words: 潮 about -6, 潮流 -3, 浪潮 -4, and 浪, 澜, 高潮, 涌, 涛
  about -0.3 to -1.
- 'situation / state of affairs' words: 势, 形势, 局势, 大局 about -2 to -1.6, and
  勢, 局, 局面 about -1 to -0.75.
- 'market / price' words: 市 (city-market sense) about -1.2, 涨幅 and 行情 about -0.6.

Every other token is predicted as 0. The prediction depends only on the current token,
so the program needs no carry. Its values are the mean activation of each word over
about 10 million training positions, so it is a per-word lookup, grouped by concept.
"""

READS = ()

KANA_SA = {"さ": -4.8, "サ": -1.3, "しさ": -2.8, "さま": -1.2}
TIDE_WAVE = {"潮": -6.0, "潮流": -3.1, "浪潮": -4.2, "浪": -1.0, "澜": -1.0, "高潮": -0.6, "涌": -0.3, "涛": -0.3}
SITUATION = {"势": -2.2, "形势": -2.4, "局势": -1.8, "大局": -1.6, "勢": -1.0, "局": -1.0, "局面": -0.75}
MARKET = {"市": -1.2, "涨幅": -0.7, "行情": -0.6}

VALUE = {}
for group in (KANA_SA, TIDE_WAVE, SITUATION, MARKET):
    VALUE.update(group)


def step(carry, prefix, upstream):
    return None, float(VALUE.get(prefix.token_strings[-1], 0.0))

programs.sol:
"""Slash boundaries, with smaller code and JSON boundary responses.

Estimates positives for word-separating slashes and newly introduced paths.
Known directory/MIME prefixes, repeated path separators, directory listings,
fractions and single letters are suppressed. Long common English words get
larger word-slash estimates. Smaller
positives mark member access, self/this receivers and JSON-key openings.
There is a weak initial negative and a strong negative on the colon of a
document-initial 'Title:' header. Memory is a 250-character document-local tail.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def common(word):
    return zipf_frequency(word.lower(), "en") >= 3.7


# Conventional Unix and source-tree directories, not ordinary slash alternatives.
DIRECTORIES = set('''
    bin sbin usr var etc tmp opt home root src lib include build dist target
    tests test docs doc assets resources packages examples scripts vendor
    node_modules workspace testbed
'''.split())
MIME_TYPES = {'text', 'application', 'audio', 'video', 'image', 'multipart'}
PRONOUNS = {'he', 'she', 'his', 'her', 'him'}


def slash_value(s, prev, tail):
    before, after = s.split('/', 1)
    if s.count('/') != 1:
        return 0.0
    if before:
        if after:
            return 0.0
        if '.' in before:
            return 0.15
        if '<' in before or '>' in before:
            return 0.1
        if '"' in before or "'" in before:
            return 1.05
        if ':' in before:
            return 1.15
        if '`' in before:
            return 0.8
        if before == ' ':
            if re.search(r'\d\s*$', tail):
                return -0.1
            if re.search(r'\b(?:file|directory):?$', tail):
                return 1.1
            return 0.5
        return 0.0
    if after and not after.isalpha():
        return -0.12
    segment = re.split(r'\s', tail)[-1]
    if not segment.isalpha():
        return -0.06
    word = segment.lower()
    if word in DIRECTORIES or word in MIME_TYPES:
        return -0.06
    p = prev.strip()
    if len(segment) == 1:
        return -0.13
    if segment.isupper():
        return 0.8
    if word in PRONOUNS or word == 'and':
        return 1.2
    if not after:
        line = tail.rsplit('\n', 1)[-1]
        if '/' in line and re.search(r'\S[ \t]{2,}\S', line):
            return -0.06
        return 0.7 if len(segment) >= 4 else 0.15
    if prev.startswith(' ') and p.isalpha():
        if len(p) >= 6 and common(p):
            return 2.5 if len(after) <= 2 else 2.1
        return 1.7 if len(p) >= 4 else 0.8 if len(p) == 3 else 0.1
    # A word split into several tokens is weaker than an immediately whole word.
    return 0.7 if len(segment) >= 6 else 0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    _, tail, prev = carry if not first else (doc, '', '')
    value = 0.0
    code = any(c in tail[-80:] for c in '{};=_')
    if first:
        value = -0.27
    elif s == ':' and tail.strip() == 'Title':
        value = -3.98
    elif '/' in s and not s.startswith('<'):
        value = slash_value(s, prev, tail)
    elif re.fullmatch(r'''[\s'"()\]]*[)\]]\.''', s):
        # Exclude prose citations and mathematical parentheses.
        call = re.search(r'([\w$]+)[([][^([\n]*$', tail)
        name = call[1] if call else ''
        mathematical = name in {'sin', 'cos', 'tan', 'log', 'ln', 'exp', 'sqrt'}
        access = (len(name) >= 2 or name == '$') and not mathematical
        if '()' in s or '"' in s or "'" in s or access:
            value = 0.7
    elif s == ' "' and tail.endswith(','):
        field_end = tail.endswith(('",', '},', '],'))
        value = 0.58 if field_end and '":' in tail else 0.0
    elif s == '(self':
        value = 0.8 if re.search(r'\bdef\s+\w+$', tail) else 0.28
    elif s.strip() in ('self', 'this'):
        indented = re.search(r'(?:\n|\\n)[ \t]{2,}$', tail)
        expression = re.search(r'(?:\breturn|\byield|[=(,$])\s*$', tail)
        if (indented and code) or expression or s.startswith('\t'):
            value = 0.4
    elif s == '::':
        value = 0.22
    elif s == '->':
        value = 0.25 if code else 0.08
    return (doc, (tail + s)[-250:], s), float(value)

"""A sparse lexical-completion approximation, not a general semantic detector.

It responds positively to glyc-/glyco- word fragments, gitignore,
selected source-code terms and compound names.  Selected System/sys
name continuations have negative responses.  A repeated middle-dot pattern
also has a negative response.  Other text is left near zero.  Token-boundary
variants sometimes have different strengths; document boundaries reset state.
"""
READS = ()

SYSTEM_MEMBERS = {
    '.Collections', '.Text', '.Data', '.Net', '.set', 'Parameters'
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, previous, tail = carry if carry else (None, '', '')
    if old_doc != doc:
        previous, tail = '', ''
    token = prefix.token_strings[-1]
    word, before = token.strip().lower(), previous.strip().lower()
    joined = bool(token) and not token[0].isspace()
    tail = (tail + token)[-80:]
    value = -0.001

    if token == previous == '··':
        value = -1.23
    elif joined and word.startswith('c') and tail.lower().endswith('gly' + word):
        # Glycosyl-, glycoprotein-, glycer-, glycol-, etc.
        value = 0.7
        if word.startswith('cos'):
            value = 4.5 if before == 'gly' else 2.8
        elif word == 'co' or word.startswith(('cop', 'can', 'cov')):
            value = 2.6
        elif word.startswith('cer'):
            value = 1.6
    elif joined and word.startswith('in') and tail.lower().endswith('glyc' + word):
        value = 0.8 if before == 'glyc' else 2.2
    elif previous.strip().lstrip('.') == 'System' and token in SYSTEM_MEMBERS:
        value = -5.5 if token == '.Data' else -2.6 if token == '.set' else -3.0
    elif before == 'sys' and word in ('.platform', '.version', '.exec'):
        value = -2.2 if word == '.exec' else -3.5
    elif before == '.springframework' and word == '.data':
        value = -3.6
    elif joined and before == 'py' and word in ('arrow', 'project', 'right'):
        value = 2.6 if word == 'right' else -2.5
    elif word == 'ignore' and before.lstrip('./') == 'git':
        value = 1.1 if before == 'git' else 2.05
    elif joined and word == 'ycl' and before == 'ps':
        value = 1.3  # First part of the split name PSyclone.
    elif joined and word == 'one' and tail.lower().endswith('psyclone'):
        value = 2.9
    elif joined and word == 'highlight' and before == 'syntax':
        value = 2.0
    elif joined and word == 'string' and before in ('doc', '/doc', '.doc'):
        value = 2.0
    elif joined and word == 'names' and before == 'class':
        value = 2.2
    elif joined and word == 'notes' and before == 'foot':
        value = 2.0 if previous.startswith(' ') else 0.95
    elif word == 'clock' and before in ('wall', 'system'):
        value = 2.0 if before == 'wall' else 2.6
    elif word in ('path', 'paths') and before.lstrip('/_') in (
        'file', 'directory', 'filesystem', 'cloud', 'yaml'
    ):
        value = 2.5 if token.isupper() and previous.isupper() else 1.0
    elif word in ('name', 'names') and before in ('user', 'family', 'qualified'):
        value = 2.0 if before == 'qualified' else 0.6
    elif before == 'civil' and word in ('rights', 'service', 'servants'):
        value = 0.6
    elif word == 'directory' and before == 'active':
        value = -2.45
    elif word in ('work', 'works') and before in ('social', 'public', 'safe'):
        value = -2.1 if before == 'social' else -0.8
    elif word in ('version', '_version') and before in ('api', 'semantic'):
        value = -0.8
    elif joined and word == 'formation' and before == 'cloud':
        value = -2.6
    elif word == 'config' and tail.lower().endswith('sysconfig'):
        value = -3.0
    elif word == 'orp' and tail.lower().endswith('hashicorp'):
        value = -2.5
    elif word == 'wrap' and before == 'py':
        value = -2.2
    elif word == 'survey' and before == 'site':
        value = -2.4
    elif word == 'profile' and before == 'community':
        value = -1.8
    elif joined and word == 'otoxic' and before == 'cyt':
        value = 1.15
    return (doc, token, tail), value

"""A sparse lexical approximation, not a universal causality detector.

An opening Title has a small positive response, followed by a strong negative
pulse on its colon. The affinity/fate/edge variants 缘, 緣, and 縁 also give
negative responses at token endings, halved inside multi-character tokens.
A short byte suffix reunites characters split across UTF-8 tokens.

Smaller rules cover selected Chinese cause/why expressions, Japanese なぜ,
English why, and Korean 인 and 연. Chinese because is stronger after adjacent
Han text. Other positions are zero; state resets between documents.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, title, tail = '', False, b''
        at_start = True
    else:
        _, previous, title, tail = carry
        at_start = previous == '<|endoftext|>'

    value = -13.31 if title and token == ':' else 0.0
    if at_start and token == 'Title':
        value = 0.56
    word = token.strip()
    previous_character = tail.decode('utf-8', errors='ignore')[-1:]
    if word.startswith(('因为', '因為')):
        adjacent_han = bool(
            regex.fullmatch(r'\p{Script=Han}', previous_character)
        )
        value = -1.4 if adjacent_han else -0.4
        if word.startswith('因為'):
            value *= 0.5
    elif word == '因':
        value = -0.65
    elif word == '故' and previous_character in {'何', '缘', '緣'}:
        value = -1.2
    elif word in {'为什么', '为何', '为啥'}:
        value = 1.8
    elif word == 'なぜ':
        value = 0.7
    elif word == 'why':
        value = -0.17
    elif word == '인':
        value = -0.75 if token.startswith(' ') else -0.12
    elif word == '연':
        value = -1.6 if token.startswith(' ') else -2.4

    tail = (tail + prefix.token_bytes[-1])[-8:]
    for character, strength in [('缘', -6.0), ('緣', -7.5), ('縁', -10.3)]:
        if tail.endswith(character.encode('utf-8')):
            value = strength
            if character in word and len(word) > 1:
                value *= 0.5
            break

    return (doc, token, at_start and token == 'Title', tail), value

"""Sparse responses to recognizable boilerplate phrase endings.

The strongest positive exception is the second digit of an initial '12'.
Other rules recognize publishing/navigation notices, file markup, tabbed
Javascript exports, patent headings, and Chinese legal/copyright phrases.
These are separate lexical triggers, not one semantic category. Repeated
middle-dot leaders are positive; the default is zero, except for a small
negative bias on a document's first token. Only a short text tail is kept,
and that state is reset between documents.
"""

READS = ()

# Chinese court decisions, and words in website copyright notices.
COURT_RULINGS = {'判决', '裁定'}  # judgment, ruling
# 'This website', delete (simplified/traditional), and contact.
NOTICE_WORDS = {'本站', '本网', '删除', '刪除', '联系'}
COPYRIGHT_NOTICE = ('版权', '版權', '免责声明', '法律声明')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail = 0, ''
    else:
        _, n, tail = carry
    token = prefix.token_strings[-1]
    text = tail + token
    value = -0.15 if n == 0 else 0.0

    if n == 1 and tail == 'Title' and token == ':':
        value = -3.08
    elif n == 1 and tail == '1' and token == '2':
        value = 6.34
    elif token == 'prints' and tail.endswith('Re'):
        value = -6.4
    elif token == 'ite' and tail.endswith('C'):
        value = -2.9
    elif token == ' permalink':
        value = -4.3 if tail.endswith('Bookmark the') else -1.6
    elif token == '.lastname' and tail.endswith('firstname'):
        value = -1.2
    elif token == ' default' and tail.endswith('\texport'):
        value = -1.84
    elif token == ' default' and '@@' in tail.split('\n')[-1]:
        value = -1.0
    elif token == ' filing' and tail.endswith('effective'):
        value = 0.86
    elif token == ' contributed' and tail.endswith('code is'):
        value = -0.8
    elif token in (' page', ' pages') and tail.endswith('preview shows'):
        value = -0.85
    elif token == ' here' and tail.endswith('You are'):
        value = -1.4
    elif token == ' \n' and tail.rstrip().endswith(
        ('APPLICATIONS', 'APPLICATION', 'INVENTION')
    ):
