    elif token and not token.strip('·') and tail.endswith('··'):
        value = 0.83
    elif token == 'pre' and tail.endswith(('></', '</')):
        value = -1.0
    elif token == ' posts' and tail.endswith('Display'):
        value = -1.45
    elif token == 'filename' and tail.endswith('<'):
        value = 2.2
    elif token == ':///' and tail.endswith('file'):
        value = 1.3
    elif token in COURT_RULINGS:
        value = -1.8
    elif token == '执行' and '判决' in tail:  # enforce a judgment
        value = -2.0
    elif token == '如下' and tail.endswith('公告'):  # 'announcement as follows'
        value = -4.2
    elif token == '到期':  # expiration, especially of a stated term
        value = 2.5 if tail.endswith('期限') else 0.8
    elif token in NOTICE_WORDS and any(w in tail for w in COPYRIGHT_NOTICE):
        value = -1.3
