    return (doc, n + 1, text[-120:]), value

programs.haiku:
"""layers.1.mlp.down_proj:4365 - a weak, mostly idiosyncratic component.

What it does, as far as concepts go:
- At the first token of a document the activation depends only on that token (attention
  sees nothing else). Newline-only tokens come out positive, capitalised words and digits
  mildly negative, lowercase words mildly positive.
- Sentence-final line breaks ('.\\n', '。\\n', '…\\n', '!\\n', '?\\n') inside running prose
  are negative, and more so when the surrounding text is non-English (non-ASCII heavy).
- Everything else is near zero, with token-specific noise of about 0.05 that no simple
  concept captures.

The program predicts those group means and 0 elsewhere.
"""

READS = ()

SENTENCE_END = set(".。!?！？…")
NON_ASCII_WINDOW = 32


def _is_word(s):
    return s.strip().isalpha()


def _doc_start_value(s):
    if "\n" in s:
        return 0.4
    if _is_word(s):
        if s[:1] == " ":
            return 0.0
        return -0.1 if s[:1].isupper() else 0.1
    if s.strip().isdigit():
        return -0.1
    return 0.0


def _line_break_value(s, prefix):
    # Sentence-final line break: the token ends a sentence and contains a newline.
    body = s.rstrip()
    if not body or body[-1] not in SENTENCE_END or "\n" not in s:
        return 0.0
    window = "".join(prefix.token_strings[-NON_ASCII_WINDOW - 1 : -1])
    non_ascii = sum(ord(ch) > 127 for ch in window) / max(len(window), 1)
    if non_ascii > 0.3:
        return -0.2
    if non_ascii > 0.1:
        return -0.1
    if non_ascii > 0.01:
        return -0.04
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return None, _doc_start_value(s)
    return None, _line_break_value(s, prefix)

programs.sol:
"""Sparse negative responses to a few document-opening strings.

The main trigger is the second digit of an opening 12 (including longer
numbers). A third 2 has a smaller response. Opening Hydro, Title:, Posted
on, and {[ have similar negative spikes. Everywhere else predicts zero.
These are literal spelling/layout triggers, not topic classifiers.
The approximation retains large spikes and drops the variable background.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        return (document, 1, token), 0.0
    _, position, opening = carry
    value = 0.0
    if position == 1 and opening == '1' and token == '2':
        value = -3.035
    elif position == 1 and opening == 'Title' and token == ':':
        value = -2.634
    elif position == 1 and opening == 'Posted' and token == ' on':
        value = -2.414
    elif position == 1 and opening == 'Hy' and token == 'dro':
        value = -4.227
    elif position == 1 and opening == '{' and token == '[':
        value = -1.339
    elif position == 2 and opening == '12' and token == '2':
        value = -1.135
    if position < 2:
        opening += token
    return (document, position + 1, opening), value

"""A short-fragment detector for the spellings pi and py.

It responds negatively to these letter pairs, including pairs split between
successive tokens. Longer words and familiar endings weaken the response.
The .py filename extension is a weaker, separate case. Greek/Cyrillic letter
spellings are matched too, but not mixed-script mathematical subscripts.
These are spelling rules, not a detector for the meaning of Python or pi.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


def script(c):
    return unicodedata.name(c, '').split(' ')[0]


@lru_cache(maxsize=32768)
def spelling(text):
    letters = []
    for c in text:
        family = script(c)
        if family == 'GREEK':
            base = unicodedata.normalize('NFD', c)[0].lower()
            # Classical letter spellings, rather than modern pronunciation.
            letters.append({'η': 'e', 'υ': 'u'}.get(base, anyascii(c)))
        elif family == 'CYRILLIC' and c.lower() in 'ыйяюёє':
            letters.append(c.lower())
        elif family in ('LATIN', 'CYRILLIC', 'ARABIC'):
            letters.append(anyascii(c))
        else:
            letters.append(c)
    return ''.join(letters).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    raw, prev = spelling(text), spelling(previous)
    s = raw.strip()
    value = 0.0

    if 'pi' in s or 'py' in s:
        if s == '.py':
            value = -0.97
        elif s.endswith('py'):
            value = -3.34 + 0.36 * min(max(len(s) - 3, 0), 4)
            if len(s) > 2 and s.isalpha():
                value += 0.55 * zipf_frequency(s, 'en')
        elif s.endswith('pi'):
            value = -1.89 + 0.23 * min(max(len(s) - 3, 0), 4)
            if s.endswith('api'):
                value += 1.52
        elif s.startswith(('pi', 'py')):
            value = -1.51 if len(s) == 3 else -0.53 if len(s) == 4 else -0.21
            if s.startswith(('pin', 'pip', 'pid')):
                value += 0.96
        else:
            value = -0.06

    same_script = previous and text and script(previous[-1]) == script(text[0])
    if prev.endswith('p') and raw and raw[0].isalpha() and same_script:
        n = min(len(s), 4) - 1
        if raw[0] == 'i':
            value += (-4.12, -2.66, -1.58, -0.92)[n]
        elif raw[0] == 'y':
            value += (-5.60, -3.68, -4.45, -0.02)[n]
        elif raw[0] in 'aeou':
            value += 0.11
        if raw[0] in 'iy' and s.startswith(('in', 'id', 'ic')):
            value += 1.57

    if prev.endswith(('pi', 'py')) and raw and raw[0].isalpha():
        value -= 0.41
    # Japanese/Korean spellings of the syllable pai (as in Python).
    if s in ('パイ', '파이') or (
        previous.endswith(('パ', '파')) and text.startswith(('イ', '이'))
    ):
        value -= 3.18
    return (doc, text), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:4367: a "spelled p-y / p-i" detector, active negatively.

What it responds to: the letters "py" or "pi" written out as text, especially when
they form a short syllable rather than part of a word. The response is strongest
for a bare token "py" (" py", "Py", "py"), then for short fragments that are
or contain "pi" (" pi", "pi", "PI", "pie", "pig", "opy"), and for a "p" that ends
one token followed by an "i" or "y" that begins the next ("cap" + "i", "P" + "IG",
"ASP" + "IRE"). Weaker negative responses come from the programming words ".py",
"python", "numpy", "scipy", and from "api". Everything else is predicted as 0.

The program reads only the current token and the previous token in the same
document. Values are in the component's own activation units, so a negative
prediction means the component pushes the residual stream the opposite way.
"""

READS = ()

# Bare "py": the strongest response.
PY_TOKEN = "py"

# Short fragments that are, or contain, the spelled syllable "pi" or "opy" / "ipy".
PI_FRAGMENTS = {
    "pi", "pie", "pig", "pix", "pit", "pic", "pir", "pis", "pil",
    "opy", "ipy", "spi",
}

# Programming words and names that contain "py" or "pi".
PY_WORDS = {".py", "python", "numpy", "scipy", "/python", "_python", "_spi"}

# Acronym fragment "api" (API), a weak response.
API_WORDS = {"api", "_api", "-api", "/api"}

# Common words that begin with i or y, so a "p" + "in" is not a spelled "pi".
FUNCTION_WORDS = {"in", "is", "it", "if", "ing"}

VALUE_PY = -3.8
VALUE_PI_FRAGMENT = -2.3
VALUE_SPLIT = -1.6
VALUE_PY_WORD = -0.7
VALUE_API = -0.3


def _norm(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    cur = _norm(prefix.token_strings[-1])
    same_doc = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    prev = _norm(prefix.token_strings[-2]) if same_doc else ""

    if cur == PY_TOKEN:
        value = VALUE_PY
    elif cur in PI_FRAGMENTS:
        value = VALUE_PI_FRAGMENT
    elif prev.endswith("p") and cur[:1] in ("i", "y") and len(cur) <= 3 and cur not in FUNCTION_WORDS:
        value = VALUE_SPLIT
    elif cur in PY_WORDS:
        value = VALUE_PY_WORD
    elif cur in API_WORDS:
        value = VALUE_API
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A sparse, signed spelling-continuation rule.

Short fragments ending in v (including Cyrillic в) respond positively to
another consonant, particularly n or ch. After h, selected a/o/u syllables
respond negatively. Tone-marked, Vietnamese-like vowel syllables strengthen
the h/v contrast. Other tokens are quiet. These rules approximate the large
spelling-boundary responses, not the component's smaller token-specific activity.
"""
import re
import string
import unicodedata
from anyascii import anyascii

READS = ()
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxz')


def toned_syllable(raw, roman):
    """A vowel syllable with Vietnamese-style tone marks and a legal coda."""
    if 'LATIN' not in unicodedata.name(raw[0], ''):
        return False
    marks = [ch for ch in unicodedata.normalize('NFD', raw[0])
             if unicodedata.combining(ch)]
    strong_tone = any(ch in '\u0300\u0309\u0323' for ch in marks)
    strong_tone = strong_tone or len(marks) > 1
    return strong_tone and bool(re.fullmatch(
        r'[aeiouy]{1,3}(?:c|ch|m|n|ng|nh|p|t|i|y|u|o)', roman))


def predict(previous, current):
    if not current or not current[0].isalpha():
        return 0.0
    p = anyascii(previous.strip()).lower().lstrip(string.punctuation)
    s = anyascii(current).lower()
    if not p or not s:
        return 0.0
    if p in ('h', 'v') and toned_syllable(current, s):
        return -2.0 if p == 'h' else 1.0
    if p.endswith('v') and len(p) <= 3:
        if s[0] not in CONSONANTS:
            return -0.05
        if s == 'ch':
            return 3.0
        if s.startswith('ch'):
            return 1.4
        if s[0] == 'n' and len(s) <= 3:
            return 1.6 if p == 'v' else (1.0 if s == 'n' else 0.25)
        value = 0.4 if p == 'v' else 0.16
        return value * (0.5 if len(s) > 4 else 1.0)
    if p == 'h':
        if re.match(r'[ao]([b-df-hj-np-tv-z])\1', s):
            return -0.45
        if len(s) > 1 and s[0] in 'aou' and s[1] in 'nlgvfsh':
            return -0.1
    return 0.0


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    return None, predict(prefix.token_strings[-2], prefix.token_strings[-1])

"""Approximate a document-onset response, especially short indentation runs.

Space-only opening tokens have a large positive response (two spaces strongest),
which falls with indentation width. Opening words are approximated by case,
leading space and English frequency. Familiar programming-language names,
collection constructors, file/format words, Unix text utilities and the word
"test" receive shared positive estimates, rather than individually learned
token values. The estimate persists while the opening token repeats; otherwise
it is zero, except for brief responses to leading "12" and "Title:".
Most lexical variation is deliberately left out.
"""
from wordfreq import zipf_frequency
import inflect

_INFLECT = inflect.engine()
LANGUAGES = set("""Python Java JavaScript TypeScript C C++ C# R Go Ruby Rust PHP
SQL Bash Perl Swift Kotlin Scala Lua MATLAB Julia Haskell Lisp Fortran
COBOL Pascal Assembly""".lower().split())
COLLECTION_TYPES = {'list', 'tuple', 'dict', 'set', 'frozenset'}
FORMATS = set("""json xml yaml yml csv tsv html css rdf toml ini markdown md
rst tex bib latex""".split())
TEXT_TOOLS = set("""cat grep sed awk cut sort uniq wc head tail tr tee paste
join split fmt fold nl comm diff""".split())
FILE_WORDS = {'file', 'path', 'directory', 'folder', 'filename', 'pathname', 'dir'}

READS = ()


def opening(s):
    if s and not s.strip(' '):
        n = len(s)
        if n == 1:
            return 0.36
        if n == 2:
            return 13.82
        if n == 3:
            return 7.80
        return max(0.0, 6.3 - 0.14 * n)
    if s.isspace():
        if s.startswith('\t') and s.endswith(' '):
            return max(0.0, 4.5 - 0.1 * s.count(' '))
        if s.startswith(' '):
            return 0.3
        if '\r' in s:
            return 0.8
        return -0.9
    if s.startswith('<|'):
        return 0.0
    w = s.strip()
    if w.lower() in LANGUAGES:
        if s.startswith(' '):
            if len(w) >= 3:
                return 4.5
        else:
            return 0.5 if len(w) == 1 and w.isupper() else 9.5
    if s == w:
        if w in COLLECTION_TYPES:
            return 16.0
        if w.lower() in FORMATS:
            return 5.0
        if w in TEXT_TOOLS:
            return 5.9
        noun = _INFLECT.singular_noun(w) or w
        if noun == 'test':
            return 7.1
        if noun in FILE_WORDS:
            return 4.5
    if w.isdigit():
        return -0.37
    if w.istitle():
        return -1.0 if s.startswith(' ') else -0.60
    if s.startswith(' '):
        return -0.57 if w.islower() else 0.54
    if w.isascii() and w.isalpha() and zipf_frequency(w, 'en') > 3.5:
        return 0.65
    return -0.11


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening(s)
        return (doc, 0, s, True, False, value), value
    _, pos, first, uniform, twos, first_value = carry
    pos += 1
    uniform = uniform and s == first
    twos = (pos == 1 and first == '1' and s == '2') or (twos and s == '2')
    value = 0.0
    if uniform:
        value = first_value
    elif twos:
        value = -5.09 * 0.34 ** (pos - 1)
