        value = 7.08
    return (doc, pos, first, uniform, twos, first_value), value

"""Approximate a multilingual grammatical-word signal.

Recent words' corpus frequencies identify Czech/Slovak. Auxiliary verbs and
reflexive clitics then give positive responses, including when a word spans
several tokens. Additional rules recognize Persian particles and letters,
Greek mood particles, split Cyrillic auxiliaries, and an initial Title label.
These are lexical approximations, not a complete account of the component.
"""
import codecs
import math
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
COMPETITORS = ('en', 'de', 'fr', 'es', 'pt', 'it', 'pl', 'hu', 'ro',
               'tr', 'id', 'fi', 'nl')
# Czech/Slovak reflexives, copulas, the conditional, and a personal pronoun.
GRAMMAR = {
    'se': 4.2, 'sa': 6.3, 'si': 3.3, 'je': 3.9,
    'js': 2.5, 'by': 5.4, 'som': 2.1, 'sme': 4.4,
    'ste': 1.8, 'sú': 4.1, 'ho': 1.9,
}
PRESENT = {'jsem': 7.6, 'jsme': 7.2, 'jsou': 5.5,
           'jsi': 5., 'jste': 5.}
PAST = frozenset(('byl', 'byla', 'bylo', 'byli', 'byly',
                  'bol', 'bola', 'bolo', 'boli',
                  'bych', 'bychom', 'byste'))
FUTURE = frozenset(('bude', 'budu', 'budou', 'budeme', 'budete',
                    'budeš', 'budem', 'budú'))
CYRILLIC_AUX = frozenset(('был', 'была', 'было', 'были', 'були',
                         'була', 'було', 'бути', 'буде', 'будет'))

@lru_cache(maxsize=80000)
def evidence(word):
    if len(word) < 3 or not all(
        'LATIN' in unicodedata.name(c, '') for c in word
    ):
        return None
    cs = max(zipf_frequency(word, 'cs'), zipf_frequency(word, 'sk'))
    other = max(zipf_frequency(word, lang) for lang in COMPETITORS)
    if max(cs, other) < 2.:
        return None
    return max(-3., min(3., cs-other))


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        word, language, previous, position, pending = '', -1., '', 0, b''
    else:
        _, word, language, previous, position, pending = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    for ch in text.lower():
        if ch.isalpha():
            word = (word+ch)[-40:]
        else:
            if word:
                ev = evidence(word)
                if ev is not None:
                    language = .85*language + .15*ev
                    # A strongly diagnostic word need not wait for a long history.
                    if ev > 2.2:
                        language = max(language, .6)
                if any(c in 'ěůřďťľĺŕ' for c in word):
                    language = max(language, .6)
            word = ''
    gate = 1/(1+math.exp(-6*(language+.05)))
    token = text.lower().strip()
    bare = word[2:] if word.startswith('ne') else word
    value = gate*GRAMMAR.get(word, 0.)
    value += PRESENT.get(bare, 0.)
    if bare in PAST:
        value += gate*4.4
    if bare in FUTURE:
        value += gate*2.9
    if bare in ('být', 'byť'):
        value += 5.4

    # Persian: the object marker ra, the prepositions ba/dar, and yeh prefixes.
    if token == 'ا':
        value += 1.04 if text.startswith(' ') else .16
    if word == 'را':
        value += 6.46
    if token == 'ر':
        value += 1.82 if text.startswith(' ') else -.52
    if token == 'با':
        value += 1.75
    if word == 'در':
        value += 1.74
    if token in ('ی', 'ي', 'ى'):
        value -= .29
    if word == 'بی':
        value -= 2.35
    if word == 'می':
        value -= 1.5
    if token in ('ی', 'ي') and len(word) == 2 and word[0] in 'پبتدکگ':
        value -= 2.35
    if token in ('س', 'سن'):
        value -= .9
    if token in ('ک', 'ك', 'گ'):
        value -= .5
    if token == 'ت':
        value -= .2

    # Greek future/subjunctive particles and Cyrillic grammatical completions.
    if word == 'θα':
        value += 4.32
    if word == 'να':
        value += 2.01
    if word == 'се':
        value += 2.47
    if word in CYRILLIC_AUX and token != word:
        value += 2.12
    if token == ':' and previous.strip() == 'Title' and position < 4:
        value += 5.41
    carry = doc, word, language, text, position+1, pending
    return carry, float(value)

"""A mostly quiet component with several document-onset responses.

Recognize millimetre abbreviations and a few formatting tokens at the start
of a document. Also approximate the negative response to bare capitals.
An identical-token run at the start stays in that onset regime. Away from
it, use small character-class baselines, except for an initial `Title:`.
Larger training activations at document onsets motivate these rules.
Token-specific variation elsewhere is deliberately left unmodelled.
