READS = ()


def onset(s):
    if s.strip() == 'mm':
        return 2.33 if s.startswith(' ') else 3.57
    if s == '··':
        return 1.45
    if s == ' .':
        return 2.03
    if s == '\\t':
        return 1.51
    if s and not s.strip('\t'):
        return 1.0
    if s == '//\n':
        return 1.67
    if s == '<|endoftext|>':
        return 1.71
    if s == 'Title':
        return 0.36
    if len(s) == 1 and s.isascii() and s.isupper():
        return -0.41
    if s.isascii() and s.isalpha() and s.istitle():
        return -0.09
    if (s.startswith(' ') and s.strip().isascii()
            and s.strip().isalpha() and s.strip().islower()):
        return 0.09
    if s.isascii() and s.isalpha() and s.islower():
        return -0.11 if len(s) == 1 else 0.04
    if s and not s.strip('()[]{}'):
        return -0.35
    if s.strip() and not s.strip().strip('#'):
        return 0.43
