def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        position, first, initial_run = 0, s, True
    else:
        position, first, initial_run = carry[1:]
        position += 1
        initial_run = initial_run and s == first
    carry = (doc, position, first, initial_run)
    if initial_run:
        return carry, onset(s)
    if position == 1 and first == 'Title' and s == ':':
        return carry, -1.68
    if len(s) == 1 and s.isascii() and s.islower():
        return carry, -0.015
    return carry, 0.0

