# Latin 'vertere' means 'turn'.
TURN_STEMS = (
    ("convert", -4.2, -6.3),
    ("invert", -3.7, -3.5),
    ("introvert", -5.8, -5.8),
    ("extrovert", -9.5, -9.5),
    ("extravert", -6.0, -6.0),
    ("revert", -5.0, -6.5),
    ("divert", -4.0, -5.0),
    ("pervert", -5.0, -6.5),
    ("subvert", -4.0, -5.0),
    ("vert", -3.2, -4.8),
)


def response(token, previous):
