            if part == "iendo":
                return -3.0
        if re.search(r"convers(?:ion|ión|ão)", word) and new("convers"):
            return -2.9 if "convers" in part else -6.0
        if word.startswith("inversion") and new("invers"):
            return -4.8
        if part == "convers":
            return -2.1
        if part == "invers":
            return -0.5
        if word.startswith(("invers", "divers")) and part in ("ores", "ión"):
            return -4.5
        if word.startswith("subvers"):
