import calendar
import re

READS = ()
MONTHS = frozenset(calendar.month_name[1:])
SHORT_MONTHS = frozenset(calendar.month_abbr[1:]) - MONTHS
NUMERALS = '一二三四五六七八九十百千万萬两兩几幾数數多半'
NUMBER = re.compile(r'(\d+|[' + NUMERALS + r']+)$')
ORDINAL = re.compile(r'\d+(?:st|nd|rd|th)$')
# Years, weeks, repetitions.
HIGH_UNITS = frozenset('年周週遍')
# Floors, books, routes, rounds, heads, bursts, paths, hands, occurrences.
COUNTERS = frozenset('楼樓本路回轮輪头頭阵陣道手次')
# Months and hours, including their classifier.
TIME_UNITS = {'个月', '個月', '个小时', '個小時'}
# Days, minutes/points, seconds.
SMALL_UNITS = frozenset('天分秒')
UNITS = HIGH_UNITS | COUNTERS | TIME_UNITS | SMALL_UNITS
NASAL_CODA = re.compile(r'u[mn][bcdfghjklmnpqrstvwxyz]*$')
JOINED = re.compile(r'^([' + NUMERALS + r']+)(.+)$')


def quantity_value(number, unit, joined):
    if joined:
        return 1.6 if unit in HIGH_UNITS else 1.5
    if unit in HIGH_UNITS:
        if number.isdigit():
            if len(number) >= 4:
                return 0.55
            if len(number) == 3:
                return 2.1
            if len(number) == 2:
                return 3.1
            return 4.5
        return 4.2 if len(number) == 1 and number not in '几幾数數多半' else 2.8
    if unit in COUNTERS or unit in TIME_UNITS:
        return 2.1
    return 0.65


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    number = NUMBER.search(before)
    value = 0.0
    if word in MONTHS or word in SHORT_MONTHS:
        if number and number.group().isdigit() and len(number.group()) <= 2:
            if word in MONTHS:
                value = -4.6 if len(number.group()) == 1 else -4.1
            else:
                value = -1.15
        elif ORDINAL.search(before):
            value = -1.55 if word in MONTHS else -0.5
        elif word in MONTHS:
            value = -0.05
    elif word == 'main' and re.search(r'\bint$', before):
        value = -4.4
    elif word in UNITS and number:
        value = quantity_value(number.group(), word, False)
    elif word in {'*', '*(', '==', '<<'} and re.search(r'[\d)]$', before):
        value = 0.65
    elif before.lower().endswith('a') and NASAL_CODA.fullmatch(token):
        value = -1.8
    else:
        joined = JOINED.fullmatch(word)
        if joined and joined[2] in UNITS:
            value = quantity_value(joined[1], joined[2], True)
    return (doc, (before + token)[-64:]), value

