"""Fires on the spelled-out word "system" and on "of" right after it.

Component layers.1.mlp.down_proj:4384 writes into the residual stream when the current
token is part of the word "system":
- a whole English word, lowercase (" system", " systems"): about 2.2;
- a capitalised whole word (" System", " Systems"): about 1.6;
- a fragment of the word that the model must join into "system": the letters "sys",
  "syst", "ystem", "SYS": about 3.7;
- a foreign spelling ("sistema", "систем", "系统"): about 3.5;
- the bare piece "ys" (as in "Stasys"): about 1.2;
- " of" directly after a system word ("system of equations"): about 5.5.
Everything else gives 0.
"""
import re

READS = ()

WHOLE_LOWER = re.compile(r"systems?")
WHOLE_ANY_CASE = re.compile(r"systems?", re.IGNORECASE)
FRAGMENT = re.compile(r"sys|^syst|^ystem$", re.IGNORECASE)
FOREIGN = re.compile(r"sistem|систем|истем|系统", re.IGNORECASE)
NOT_SYSTEM = re.compile(r"systemat|systemic", re.IGNORECASE)


def system_value(token):
    """How strongly one token (decoded alone) is the word 'system' or a piece of it."""
    word = token.strip()
    if NOT_SYSTEM.match(word):
        return 0.0
    if WHOLE_LOWER.fullmatch(word):
        return 2.2
    if WHOLE_ANY_CASE.fullmatch(word):
        return 1.6
    if word == "ys":
        return 1.2
    if FRAGMENT.search(word):
        return 3.7
    if FOREIGN.search(word):
        return 3.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip() == "of" and len(prefix.token_strings) > 1:
        if WHOLE_ANY_CASE.fullmatch(prefix.token_strings[-2].strip()):
            return carry, 5.5
    return carry, system_value(token)

