"""A sparse mixture of surface cues, not a single semantic category.

The largest ordinary cue is digit 3, with weaker responses to other
forms of three and to March. Contracted apostrophe-s after pronouns is
positive; ordinary possessives are not. Other cues include truth values,
right/left, ellipses, primes, formatting marks, Greek vowels and byte
fragments. Most tokens get zero, with a coarse document-start bias.
Initial Title: headings and a few repeated punctuation prefixes are
outliers handled separately. Vocabulary-specific variation is omitted.
"""
import re
import unicodedata as ud

READS = ()
CONTRACTION_BASES = {
    'it', 'that', 'what', 'there', 'here', 'who', 'how', 'where', 'he', 'she'
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0, True, '')
    _, previous, position, dots, initial_run, word_tail = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    text = token.strip()
    initial_run = initial_run and (position == 0 or token == previous)
    value = 0.0

    if text == '3':
        value = 0.665
    elif text.lower() in {'three', 'third'}:
        value = 0.39
    elif text in {'³', '₃', '三', 'III'}:
        value = 0.53
    elif text == 'March':
        value = 0.52
    elif text.lower() in {'true', 'false'}:
        value = 0.66
    elif token == ' right':
        value = 0.73
    elif token == ' left':
        value = -0.10
    elif token == 'left':
        value = -0.34
    elif token in {"'s", '’s'}:
        value = 0.77 if word_tail.lower() in CONTRACTION_BASES else -0.03
    elif text in {"'", '’'}:
        preceding = word_tail
        prime = preceding.isdigit() or (
            len(preceding) == 1 and preceding.isascii() and preceding.isalpha()
        )
        value = 0.56 if prime and token == text else 0.06
    elif text in {'...', '…'}:
        value = 0.68 if token.startswith(' ') else 0.54
    elif text == '.' and previous.strip() == '.':
        value = min(0.9, 0.3 + 0.1 * dots)
    elif text == '**':
        value = 0.33
    elif text in {'!', '?'}:
        value = 0.14
    elif text == '$':
        value = 0.21
    elif text == 'arguments':
        value = 0.48

    if len(text) == 1:
        base = ud.normalize('NFD', text)[0]
        if base in 'ηω' or (base == 'ε' and text != base):
            value = 0.68
    if text == '\ufffd':
        value = 0.34 if all(128 <= b < 192 for b in raw) else 0.14

    if position == 0:
        value = -0.16 if not text else 0.42
    if initial_run and text == '··':
        value = -0.55
    if initial_run and text and set(text) == {'^'} and len(text) >= 4:
        value = -1.87
    if position == 1 and previous == 'Title' and token == ':':
        value = -6.289

    if initial_run and token == '\r':
        value = -1.67

    match = re.search(r'[A-Za-z0-9]+$', word_tail + token)
    word_tail = match.group()[-32:] if match else ''
    dots = dots + 1 if text == '.' else 0
    state = (doc, token, position + 1, dots, initial_run, word_tail)
    return state, value

programs.haiku:
"""layers.1.mlp.down_proj:4385 -- a weak, diffuse MLP feature in layer 1.

What it does, in plain terms: it is mostly silent, and it lights up on a small set of
recognisable things:

  * the digit "3" (any width: 3, ３, ³) -- strongest and most reliable, about 0.65;
  * number words for three ("three", "third", "III", "三", "第三") -- about 0.43;
  * truth words "true" / "false" (any case) -- about 0.69, and "right" -- about 0.5;
  * ellipses "..." and "…" -- about 0.46;
  * the "'s" of a contraction after it / that / there / what / he / here / let
    (the "is" in "it's", "that's") -- about 0.75; other 's (possessive) -- about 0.19;
  * fragments of a multi-byte character that decode alone to U+FFFD -- about 0.19;
  * the first token of every document (the model resets there) -- an extra +0.38.

Everything else predicts 0. The values are the mean activations of each group, fitted
by least squares on training rows. Variance explained is about 0.27 on 5k training rows
and 0.26 on the eval rows: the rest is spread over thousands of tokens with small,
context-dependent values, which a short program does not capture.

Main program: `step` below, run per token; `prefix` gives the current token and the
previous one, and the document labels to detect document starts.
"""

READS = ()

THREE = {"3", "３", "³"}                                  # the digit three, any width
THREE_WORDS = {"three", "third", "iii", "-three", "-third", "三", "第三"}
TRUTH = {"true", "false"}                                 # truth values, any case
RIGHT = {"right", "rights"}
ELLIPSIS = {"...", "…", ",...", ",…"}
CONTRACTION_HOSTS = {"it", "that", "there", "what", "he", "here", "let"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    bare = tok.strip()
    word = bare.lower().lstrip("=(.-")
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if bare in THREE:
        v = 0.65
    elif bare.lower() in THREE_WORDS:
        v = 0.43
    elif word in TRUTH:
        v = 0.69
    elif word in RIGHT:
        v = 0.5
    elif bare in ELLIPSIS:
        v = 0.46
    elif bare in ("'s", "’s"):
        prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
        v = 0.75 if prev in CONTRACTION_HOSTS else 0.19
    elif "�" in tok:
        v = 0.19
    else:
        v = 0.0
    if doc_start:
        v += 0.38
    return carry, float(v)

programs.sol:
"""A spelling detector centered on rough/ruff and nearby r-vowel syllables.

It responds most strongly to 'rough' or to 'uff' completing an r. It excludes
through and truffle, carries the rough response into derivational suffixes,
and distinguishes a lone r from consonant clusters. Small negative rules
cover rumor and literal r notation; Chinese 粗 ('coarse') is positive too.
All other tokens are nearly silent.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    p, pp = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    s, p0 = text.lower(), p.lower()
    w, r = s.lstrip(), p0.strip()
    value = -0.002
    through = not text[:1].isspace() and p0.endswith(('th', 't'))
    if w in {'rough', 'roughly'}:
        value = -0.5 if through else (9.1 if w == 'rough' else 5.3)
    elif r == 'rough' and not s[:1].isspace():
        if p == p.strip() and pp.lower().endswith(('th', 't')):
            value = 0.0
        elif s in {'er', 'est', 'ness', 'ly'}:
            value = 6.7
        elif s.startswith('en'):
            value = 3.5
    elif w in {'rud', 'rude', 'rue', 'rut', 'ruth'}:
        value = 2.2
    elif p0.endswith('r') and s and not s[0].isspace():
        alone = not p0[-2:-1].isalpha()
        vowel_before_r = len(p0) > 1 and p0[-2] in 'aeiou'
        if s == 'uff':
            value = 13.0 if alone else 0.2
        elif s.startswith('uff'):
            value = 3.5 if alone else 0.1
        elif s.startswith('uda'):
            value = 5.2
        elif len(s) <= 3 and s.startswith(('ud', 'ue', 'ut', 'uf', 'uh')):
            value = 2.8 if alone else (1.8 if vowel_before_r else 0.4)
        elif s in {'u', 'ui', 'up', 'uk'}:
            value = 1.7 if alone else 0.0
        elif s in {'aff', 'agh'}:
            value = 4.7 if alone else 0.2
        elif s.startswith('aph'):
            value = 1.65
        elif s == 'wh':
            value = 1.4
        elif len(s) <= 3 and s.startswith('ü'):
            value = 3.2 if s == 'ü' and alone else 0.8
        elif s.startswith('oh') and alone:
            value = 1.2
        elif s in {'ur', 'umble', 'une', 'uby'} and alone:
            value = -1.4
        elif s in {"'", '"'} and p.strip() == 'R':
            value = 2.4
        elif s == '$' and p.strip() == 'R':
            value = 2.0
        elif s[0].isdigit() and alone:
            value = -0.3
    elif r == 'р' and text in {'у', 'уд'}:
        value = 3.5
    elif r == 'ر' and s == 'ا':
        value = -2.45
    elif text == '粗':
        value = 3.2  # Chinese 'coarse/rough'.
    if p0.endswith('rum') and s.startswith(('or', 'our')):
        value = -6.0
    if s == '.rs':
        value = -0.66
    # Repeated middle-dot leaders and the r/w/- alphabet of Unix permissions.
    if s == '··' and p0 == s:
        value = -1.04
    elif p0 == 'w' and s == '-r':
        value = -3.9
    elif p0.endswith('-r') and s == 'w':
        value = -1.03
    elif p0 in {'-r', 'r'} and s == '--':
        value = -1.74
    elif p0 == '--' and s == 'r':
        value = -3.2
    return (doc, text, p), value

"""A short-token spelling heuristic, mainly for gan-like syllables.

Negative cues are 'gan' inside a token, nasal completions after a token
ending in g, and grant/graft/transplant stems. Long continuations and very
common complete English words weaken the spelling cue. Short o-bearing
completions after g and repeated middle dots have small positive values.
Only the previous token is retained; document boundaries reset it.
"""
import math
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def spelling(token):
    names = [unicodedata.name(c, '') for c in token if not c.isascii()]
    if any('CJK' in name for name in names):
        return '', 0.0
    weight = 1.0
    if any('HANGUL' in name for name in names):
        weight = 0.1
    elif any('LATIN' in name and ' AND ' in name for name in names):
        weight = 0.1
    elif any('LATIN' in name for name in names):
        weight = 0.5
    # Keep the palatal nasal distinct from n; retain Arabic alef's vowel.
    text = token.replace('ñ', '~').replace('Ñ', '~').replace('ا', 'a')
    return anyascii(text).lower().strip(), weight


@lru_cache(maxsize=4096)
def unfamiliarity(word):
    return max(0.03, min(1.0, (5.0 - zipf_frequency(word, 'en')) / 0.5))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s, weight = spelling(token)
    continuing = bool(token and not token[0].isspace() and s[:1].isalpha())
    value = 0.0

    match = re.search('gan', s)
    if match:
        distance = 0.4 * match.start() + 0.9 * (len(s) - match.end())
        value -= 6.45 * math.exp(-distance) * unfamiliarity(s) * weight
    if s == 'grant':
        value -= 4.65 if token.strip()[:1].isupper() else 1.36
    if 'graft' in s:
        value -= 4.27
    if 'transplant' in s:
        value -= 2.03
    elif continuing and 'transplant' in previous + s and 'transplant' not in previous:
        value -= 2.86

    strength = (3.0 / max(2, len(s))) ** 0.8 * weight
    if continuing and previous.endswith('g'):
        if s.startswith('an'):
            nasal = 0.5 if re.match('an[aeiou]', s) else 1.0
            value -= 4.92 * strength * nasal
        elif s.startswith('am'):
            value -= 2.15 * strength * (1.0 if s == 'am' else 0.3)
        elif s.startswith('on'):
            value -= 1.42 * strength
        elif re.match('[rlh]an', s):
            value -= 2.09 * strength
        elif s.startswith('raf'):
            value -= 7.66 * strength
        if 'o' in s:
            value += 0.34 * weight * math.exp(-max(0, len(s) - 3))
    if continuing and re.search('g[rlh]$', previous) and s.startswith('an'):
        value -= 0.88 * strength
    if continuing and previous.endswith('gra') and s.startswith('ft'):
        value -= 4.59
    if len(token.strip()) >= 2 and set(token.strip()) == {'·'}:
        value += 1.49
    return (doc, s), float(value)

programs.haiku:
"""Negative dips on the spelling "gan" when it appears as a piece of a word.

Layer 1's MLP writes this component into the residual stream. It is almost silent
(it fires on about 0.1% of tokens), but where it fires it fires hard, always downward,
and the big dips are all one idea: the letters g-a-n (or "organ", "grant", "graft")
written as a separate piece of a word or name:

  - strongest: "gan" itself, and names ending in it: "Dehgan", "Egan", "Hogan" (-5 to -10)
  - "graft" in "xenograft"; "organ" ("organist", "male sex organ") and "organs" (-4)
  - "grant" ("Federal Pell Grant"), "Gang", "Morgan", "Logan", "vegan" (weaker, -2 to -3)
  - a piece starting "an", "am", "and", "ant", "ang" right after a piece ending in "g":
    "Ig" + "AN" (IgAN), "Ashwag" + "and" (Ashwagandha), "lag" + "am" (-3 to -8)

Whole common words that contain the letters, such as "organization", "began",
"organic", "aircraft" or "granted", stay at 0: the dip is on the spelling piece only.
Predictions are 0 everywhere else; the small diffuse part of the signal is left out.
"""

READS = ()

STRONG = {"gan", "igan", "agan", "egan", "ogan", "hogan", "rgan", "graft", "rafted"}
ORGAN = {"organ", "organs"}
WEAK = {"grant", "grants", "gang", "gangs", "morgan", "logan", "vegan"}
ENDINGS = {"an", "am", "and", "ant", "ang", "ani", "ans", "ano"}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().lower()
    raw = prefix.token_strings[-1].lower()
    if piece in STRONG:
        return carry, -7.0
    if piece in ORGAN:
        return carry, -4.5
    if piece in WEAK:
        return carry, -2.5
    if prefix.position > 0:
        before = prefix.token_strings[-2].lower()
        if before.endswith("g") and raw in ENDINGS:
            return carry, -5.0
    return carry, 0.0

programs.sol:
"""Line-ending punctuation, blank lines, and document-opening title markers.

The main response is negative at sentence/paragraph boundaries. A space before
a two-newline break makes it stronger, especially after a sentence end.
Short labels and extremely long lines have weaker responses than prose lines.
Code delimiters have smaller, sometimes positive, line-ending responses.
The separate opening-Title: response is unusually large. Ordinary text is near
zero. State tracks document age, line length, token count, and previous token.
"""
READS = ()
SENTENCE_END = tuple('.?!。！？')


def line_ending(text, previous, chars, tokens):
    breaks = text.count('\n')
    body = text.rstrip('\r\n')
    mark = body.strip()
    sentence = any(c in mark for c in '.?!')
    cjk_sentence = any(c in mark for c in '。！？：')
    prev = previous.rstrip()
    if breaks == 2:
        if body == ' ':
            if prev.endswith(SENTENCE_END):
                return -1.30 if chars < 400 else -1.02
            if tokens <= 2:
                return -0.55
            return -0.82 if prev and prev[-1].isalnum() else -1.09
        if sentence or cjk_sentence:
            if chars >= 400:
                return -0.53
            return -0.88 if 65 <= chars <= 250 else -0.78
        if ':' in mark:
            return -0.65 if ')' in mark else -0.88
        if ',' in mark:
            return -0.74
        if '`' in mark:
            return -0.96
        return -0.26
    if breaks >= 3:
        return -0.27 if ':' in mark else -0.03
    if cjk_sentence:
        return -0.54 if chars <= 135 else -0.31
    if sentence:
        if chars >= 400:
            return -0.09
        if tokens <= 2:
            return -0.10
        return -0.27 if tokens <= 17 else -0.39
    if body == ' ':
        if tokens <= 1:
            return 0.07
        if tokens <= 3:
            return -0.07
        return -0.35 if tokens <= 87 else -0.13
    if not body and prev.endswith(SENTENCE_END):
        return -0.34
    if ',' in mark:
        return -0.20 if any(c in mark for c in '\"\'') else -0.09
    if ':' in mark:
        return 0.10 if ')' in mark else -0.09
    if '`' in mark:
        return -0.25
    if '{' in mark:
        return -0.12 if body.startswith(' ') else 0.24
    if '}' in mark:
        return 0.06 if body.startswith(' ') else 0.15
    return -0.03 if body.startswith(' ') else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age, chars, tokens = '', 0, 0, 0
    else:
        _, previous, age, chars, tokens = carry
    text = prefix.token_strings[-1]
    value = -0.003
    if '\n' in text:
        value = line_ending(text, previous, chars, tokens)
        chars, tokens = len(text.rsplit('\n', 1)[-1]), 0
    else:
        chars, tokens = chars + len(text), tokens + 1
    if text == '<|im_start|>':
        value = 0.44 if age == 0 else 0.05
    if age == 0:
        if text == 'Title':
            value = 2.84
        elif text == '#':
            value = 0.71
        elif text == '##':
            value = 2.18
    elif age == 1 and previous == 'Title' and text == ':':
        value = -14.63
    return (doc, text, age + 1, chars, tokens), value

programs.haiku:
"""Paragraph-break detector (negative), for layers.1.mlp.down_proj:4389.

The component writes a negative signal on line-break tokens that end a sentence:
  * a blank line (two or more newlines, \r\n\r\n counted the same) right after
    sentence-final punctuation (. ? ! : , 。) is strongly negative (about -0.8),
    most of all a space followed by a blank line after a period (about -1.2);
  * a blank line after other text is mildly negative (about -0.3);
  * a single newline after a period, question mark, or 。 is mildly negative
    (about -0.3 to -0.5), after ! weaker;
  * all other tokens, including code-style newlines after { ; ) }, are about 0.
Carriage returns are ignored, so \r\n breaks behave like \n breaks.
Each value is the mean activation for that class on training rows.
