import math
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def start_pulse(text):
    word = text.strip()
    if text.startswith('<|'):
        return -14.65
    if not word:
        if text == ' ':
            return -1.76
        if '\t' in text:
            return -12.9 if text == '\t' else -9.5
        if '\n' in text:
            return -6.6 if text == '\n' else -4.9
        return -2.5 - 0.5 * math.log(max(1, len(text)))
    if word.isdigit():
        return -5.8 if word == '0' else -8.75
    if any(c.isalpha() for c in word):
        latin = bool(regex.search(r'\p{Script=Latin}', word))
        han = bool(regex.search(r'\p{Script=Han}', word))
        value = -13.6
        if latin:
            value += 0.42 * zipf_frequency(word.lower(), 'en')
        elif han:
            value += 3.2
        else:
            value += 0.8
        if word[0].isupper():
            value -= 0.6
            if not text[0].isspace():
                value -= 4.6
            if not latin and not han:
                value -= 2.8
        if not word.isalpha():
            value += 0.65
        return value
    value = -4.7 - 1.7 * math.log1p(len(word))
    if any(c in '.,;:!?' for c in word):
        value += 1.1
    if '\\' in word or '#' in word:
        value -= 2.0
    if '\ufffd' in word:
        value -= 3.1
    return value


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pulse = start_pulse(text)
        carry = (doc, token, True, pulse)
    else:
        doc, first_token, uniform, pulse = carry
        uniform = uniform and token == first_token
        carry = (doc, first_token, uniform, pulse)
    if carry[2]:
        return carry, carry[3]
    if len(text) > 1 and text.endswith(('"', "'")) and all(
            c in ' \\([=:' for c in text[:-1]):
