        elif text in (' "', " '"):
            value = 0.85 if previous.endswith(',') and text[-1] == "'" else 0.2
        elif '\\' in text:
            value = 0.15 if previous[-1:].isalpha() else 0.4
        else:
            value = 0.5
        return carry, value
    return carry, 0.0

