"""layers.1.mlp.down_proj:4390 -- a "document-opening token" detector.

This component is almost silent everywhere except on the first token of a document
(the first token of each packed document, and the first token of each row). There it
writes a large negative value into the residual stream, and the size depends only on
what that first token is:

  * special markers such as <|endoftext|> or <|im_start|>      about -15
  * a capitalised word (first character upper case)            about -16
  * any other word (contains a letter)                         about -12
  * a digit                                                    about -8
  * punctuation, symbols, code, whitespace                     about -6

Every other position predicts 0. The value at a document start does not depend on
the context before it (the first token attends only to itself), so the token alone
decides it. The numbers are means measured over the training corpus's document starts.
"""

import unicodedata

READS = ()


def _is_special(token):
    return token.startswith("<|") and token.endswith("|>")


def _has_letter(token):
    return any(unicodedata.category(ch).startswith("L") for ch in token)


def _value(token):
    if _is_special(token):
        return -14.7
    if _has_letter(token):
        return -16.5 if token[:1].isupper() else -11.6
    if token.strip().isdigit():
        return -8.1
    return -5.6


def step(carry, prefix, upstream):
    # A document starts at the row's first token, or wherever the document id changes.
    docs = prefix.document_ids
    starts_doc = prefix.position == 0 or docs[-1] != docs[-2]
    if not starts_doc:
        return None, 0.0
    return None, float(_value(prefix.token_strings[-1]))


def main():
    # Quick check on a few hand-written tokens (run locally, no model needed).
    for token in ["The", " the", "<|endoftext|>", "42", "//", "II"]:
        print(repr(token), _value(token))


if __name__ == "__main__":
    main()

