def language_offset(recent):
    letters = [c for s in recent if not (s.startswith('<') and s.endswith('>'))
               for c in s if c.isalpha()][-100:]
    total = 0.0
    for c in letters:
        name = unicodedata.name(c, '').split(' ')[0]
        if name == 'CYRILLIC':
            total -= 1.06
        elif name == 'ARABIC':
            total -= 1.47
        elif name in ('CJK', 'HANGUL', 'HIRAGANA', 'KATAKANA'):
            total -= 0.60
