            value = -4.27 - 0.29 * early + 0.85 * language
        elif token == '</think>':
            value = -0.75 + 0.5 * language
        elif token == '<|im_end|>':
            value = -0.01 + 0.44 * early + 0.5 * language
            value -= 0.28 * after_call + 0.16 * after_result
        elif token == '<tool_response>':
            value = -2.36 + early
        elif token == '</tool_response>':
