each document, by an amount set by what kind of token it is (candidate 2)."""

READS = ()


def value_for(tok):
    body = tok.lstrip(" ")
    first = body[:1]
    if tok.startswith("<|"):
        return -15.0            # chat / special markers
    if first == "" or first.isspace():
        return -6.0             # bare whitespace or newlines
    if first.isascii() and first.isalpha():
        if tok.startswith(" "):
            return -9.0         # word with a leading space
        return -15.0 if first.isupper() else -13.0
    if first.isalpha():
        return -9.5             # non-ASCII letters (CJK, Cyrillic, ...)
    if first.isdigit():
        return -4.5
    if first in "#/":
        return -6.0             # comment markers
    if first.isascii():
        return -6.5             # other ASCII punctuation
    return -6.5


def step(carry, prefix, upstream):
    p = prefix.position
    if p > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return carry, 0.0       # inside a document: the component is silent
    return carry, value_for(prefix.token_strings[-1])

