            return -0.38 if large else -0.13
        if unit in {'word', 'words'}:
            return -0.65
    if prev == 'best' and w == 'possible':
        return 2.0
    if prev == 'the' and w == 'first':
        return 0.19
    if w == 'than':
        return 1.25 if prev == 'fewer' else -0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    value = response(history, raw)
    return (doc, (*history[-5:], raw)), value

programs.haiku:
"""v6: word-level rules for the token 'to' and a few related words, plus unit-after-number.
The biggest activations are (a) 'to' that follows a number, a time span or an 'ease /
likelihood / next' word ('1 to 5', 'minutes to', 'likely to', 'easy to', 'first to'), and
(b) a unit written right after a number ('2 h', '30 min', '320 px'), which is negative."""
READS = ()

NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
                "million", "billion", "half"}
TIME_SPANS = {"second", "seconds", "minute", "minutes", "hour", "hours", "day", "days", "week",
              "weeks", "month", "months", "year", "years", "moment", "percent", "%"}
EASE_WORDS = {"easy", "easier", "simple", "quick", "apt", "inclined", "slower", "longer", "take",
              "takes", "time", "best", "next", "chance", "more"}
# unit abbreviations written right after a number, with their typical activation
UNITS = {"h": -1.6, "hour": -0.7, "hours": -0.4, "min": -1.3, "minutes": -0.4, "px": -1.1,
         "m": -0.5, "km": -0.5, "meter": -2.0, "metres": -0.4, "mm": -0.2, "cm": -0.2, "ft": -0.4}
QUANTITY_WORDS = {"more", "much", "some", "no", "less", "little"}

def is_number(s):
    return s != "" and all(c.isdigit() for c in s)

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    raw = toks[-1]
    tok = raw.strip()
    prev = toks[-2] if len(toks) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    p = prev.strip()
    if raw == "assistant" and prev == "<|im_start|>":
        return carry, -0.73          # chat-template role header
    if raw == "_page" or (tok == "page" and p == "per"):
        return carry, 4.0            # "per_page" / "per page"
    if tok == "likely":
        return carry, 5.0 if p in ("more", "less", "as") else (1.7 if p == "most" else 0.0)
    if tok == "recent" and p == "most":
        return carry, 2.5
    if tok == "first" and p == "the":
        return carry, 0.3
    if tok == "to":
        if p == "first":
            return carry, 4.0
        if p == "likely":
            return carry, 2.3
        if is_number(p) or p in NUMBER_WORDS or p in TIME_SPANS:
            return carry, 1.0
        if p in EASE_WORDS:
            return carry, 0.9
        return carry, 0.0
    if is_number(p) and tok in UNITS:
        return carry, UNITS[tok]
    if tok == "time" and p in QUANTITY_WORDS:
        return carry, -1.5
    return carry, 0.0

programs.sol:
"""A short sen/cen/zen/xen spelling-fragment detector.

The ending may arrive across a token boundary. Short fragments are strongest;
longer, familiar words usually have much smaller responses. Transliteration
extends the spelling test to other scripts. These rules approximate the main
positive response, not the component's scattered negative responses. Common
German inflections, silent French endings, and misleading transliterations
are attenuated.
"""
import regex as re
from codecs import utf_8_decode
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def roman(text):
    return anyascii(text).lower()


@lru_cache(maxsize=16384)
def frequency(word, language='en'):
    return zipf_frequency(word, language)


def strength(token, start, end, syllable, previous, word):
    """Distinguish syllable-sized pieces from longer lexicalized tokens.

    A negative start means the spelling began in an earlier token.
    """
    size = len(token.strip())
    before = token[:max(0, start)].lstrip()
    after = token[end:]
    if after.startswith('g'):
        return 0.0
    common = frequency(token.strip())
    word_common = frequency(word)
    if start == -2 and token == 'n':
        return 5.5
    if size <= 3:
        if word_common > 3.8:
            return 5.1
        if size <= 2:
            if len(word) > 9:
                return 0.6
            return 2.4 if previous.endswith('s') else 1.5
        if syllable == 's':
            return 5.0 if start >= 0 else 3.0
        return 3.1 if common < 3.5 else 1.5
    if size <= 5:
        if common > 4.9:
            return 0.8 if after.startswith('t') else 0.15
        if word_common > 4.2:
            return 2.6
        return 1.3 if len(word) <= 10 else 0.4
    if after == 't':
        if before.endswith('s'):
            return 3.8 if len(before) <= 3 else 0.1
        if len(before) <= 2:
            return 1.3
        if len(before) == 3:
            return 1.4 if common < 4.7 else 0.3
        return 0.05
    if after == 'ce' and len(before) <= 2:
        return 1.2
    if after.startswith('at'):
        return 0.9
    if start < 0 and len(after) <= 4:
        return 0.9
    return 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'')
    _, previous, pending = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = utf_8_decode(raw, 'ignore', False)
    left, token = roman(previous[-2:]), roman(text)
    matches = [m for m in re.finditer('[sczx]en', left + token)
               if m.end() > len(left)]
    value = 0.0
    if matches:
        m = matches[-1]
        words = re.findall(r'\w+', previous + text)
        word = words[-1] if words else ''
        value = strength(token, m.start() - len(left), m.end() - len(left),
                         m.group()[0], left, word)
        if re.fullmatch(r'\p{Han}', text):
            value = 3.8 if token == 'sen' else 0.0
        # Transliteration must not turn palatal nasals or na/ni into n.
        if 'ñ' in text.lower() or text.endswith('ení'):
            value = 0.0
        if (m.start() < len(left) and token.startswith('n')
                and re.match(r'[\p{Hiragana}\p{Katakana}]', text)
                and not text.startswith(('ん', 'ン'))):
            value = 0.0
        # Downweight likely German inflections and French silent endings.
        if (m.start() >= len(left) and len(token.strip()) <= 3
                and frequency(word, 'de') > max(3.7, frequency(word) + 1)):
            value *= 0.25
        if (word.lower().endswith('ent')
                and frequency(word, 'fr') > max(3.5, frequency(word) + 1)):
            value *= 0.1
        # Give extra weight to syllables completed by a UTF-8 continuation.
        if pending:
            value *= 1.7
    # Unwritten short vowels in Arabic-script consonant spellings.
    if not matches and re.search(r'\p{Arabic}', previous[-2:] + text):
        for m in re.finditer(r"[sz]y?'?n", left + token):
            if m.end() > len(left):
                value = 2.2 if len(left + token) - m.end() <= 2 else 0.3
    return (doc, (previous + text)[-35:], raw[used:]), value

programs.haiku:
"""Spelling detector for the 'sen' / 'cen' / 'zen' sound that closes a word or name.

What it does, in plain terms: the component reads the letters of the word it is
in, as they are spelled so far. It fires on the piece that completes an
s-e-n, c-e-n-t or z-e-n ending:

- the piece "sen" itself, as in Sun Yat-|sen|, Gulbran|sen|, Jacob|sen| (strongest);
- a bare "en", "ent", "ens" or "ene" piece (Latin, Cyrillic "ен"/"ент") that
  completes a word ending in -sen, -cen or -zen: Madsen, Larsen, Hazen, recent,
  descent, consent, absence;
- the pieces "cent" and "zen" (medium);
- any other piece of such a word, a little less, and more when the word is
  capitalised (a name) than when it is lower case;
- any other piece with "sen" or "cen" inside, a trace.

Everything else, including ordinary 'en' pieces (st-en, m-en, ch-en), is 0.
Why: the component is a spelling feature for the -sen / -cent sound of names
and rare words; the values are the mean activations per case measured on
training text.
"""
import re

READS = ()

# A word whose letters end in s/c/z + en, optionally followed by t or s (Cyrillic too).
NAME_END = re.compile(r"[scz]en[ts]?$|[сцз]ен[тс]?$")


def word_so_far(strings):
    """The word ending at the newest token: its text as written, and its lower-case letters."""
    parts = []
    for s in reversed(strings):
        parts.append(s)
        if not s[:1].isalpha():
            break
    text = "".join(reversed(parts)).strip()
    letters = "".join(c for c in text if c.isalpha())
    return text, letters.lower()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    piece = tok.strip().lower()
    text, word = word_so_far(prefix.token_strings)
    name_end = NAME_END.search(word) is not None
    if piece in ("sen", "セン"):
        value = 5.0
    elif piece in ("en", "ent", "ens", "ene", "ен", "ент") and name_end:
        value = 3.5
    elif piece in ("cent", "zen"):
        value = 2.0
    elif name_end:
        value = 1.1 if text[:1].isupper() else 0.65
    elif "sen" in piece or "cen" in piece:
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Quotation endings, and negative responses to absolute filesystem paths.

A comma closing a sentence-like quotation is the strongest positive case,
especially with I/we/you or an auxiliary verb. Questions and exclamations are
weaker. Single and low-left/high-left quotation conventions are recognized.
Common absolute-path directories have a separate negative response; whether
the slash shares their token matters. Repeated middle-dot pairs and a tool-call
delimiter are additional formatting cases. Other positions usually predict zero.
"""
import re

READS = ()
PERSONAL = set('i me my mine we us our ours you your yours'.split())
AUXILIARIES = set('is are was were be have has had do does did will would '
                  'can could should must may might'.split())
ROOTS = {'workspace': -0.68, 'usr': -0.44, 'opt': -0.74,
         'Users': -1.0, 'home': -0.70, 'tmp': -0.30,
         'root': -0.45, 'bin': -0.60}


def quotation_value(token, before):
    # Punctuation INSIDE the closing marks, not JSON's quote-comma.
    if '\n' in token:
        return 0.03
    end = token.strip()
    closing = '\"\'”’»'
    comma_close = bool(re.fullmatch(r",[\"'”’»]+", end))
    boundary = max(before.rfind(q) for q in '\"“”«»„')
    # In Czech/German typography, high-left quotes can close low-left ones.
    if end == '“' and boundary >= 0 and before[boundary] == '„':
        comma_close = before.endswith(',')
    if not comma_close:
        if any(p + q in end for p in '?!？！' for q in closing):
            return 0.32
        if any(p + q in end for p in '.。' for q in closing):
            return 0.12 if '。' in end else 0.04
        return 0.0
    # Apostrophes within words are not opening single quotation marks.
    if "'" in end and not any(q in end for q in '\"”»'):
        openings = list(re.finditer(r"(?<!\w)'(?=\w)|``", before))
        if openings:
            boundary = openings[-1].end() - 1
    content = before[boundary + 1:].strip().lstrip('([{')
    words = re.findall(r'[^\W\d_]+', content.lower())
    if any(c in content for c in '{}_=\\'):
        return 0.02
    capital = bool(content and content[0].isupper())
    if not capital:
        return 0.12 if '”' in end else 0.02
    if PERSONAL.intersection(words):
        return 1.20
    contraction = re.search(r"\b(?:it|he|she|that|there)['’]s\b",
                            content.lower())
    if AUXILIARIES.intersection(words) or contraction:
        return 1.10
    return 0.55 if '”' in end else 0.45


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '··':
        value = 1.11
    elif token in ROOTS and before.endswith(('/', '\\')):
        value = ROOTS[token]
    elif token == '/local' and before.endswith('usr'):
        value = -0.71
    elif token == '/lib' and before.endswith(('usr', '/local')):
        value = -0.48
    elif token == '/workspace':
        value = -0.15
    elif token == '<tool_call>':
        value = 0.11
    elif any(q in token for q in '\"\'“”’»'):
        value = quotation_value(token, before)
    return (doc, (before + token)[-2500:]), value

programs.haiku:
"""Activation of the MLP unit that fires on verbs of perception and encounter.

The unit is strongest on the verb that introduces something taken in by the senses
("I could HEAR ...", "to WATCH ...", "I have SEEN ...", "I NOTICED ..."). Weaker on
verbs of finding, meeting and reasoning about something, and on the article or
preposition right after such a verb ("look AT", "listen TO", "sight OF"). Near zero
elsewhere, and slightly negative on the first token of a document.
"""
READS = ()

# verbs of hearing, seeing and watching (plus a few foreign words for them)
SENSE = {
    " hear": 3.5, " heard": 3.6, " hears": 3.0, " hearing": 2.5,
    " see": 2.5, " seen": 2.1, " saw": 2.5, " sees": 1.5, " seeing": 2.0,
    " watch": 3.0, " watching": 2.4, " watched": 2.5, " watches": 2.5,
    " noticed": 3.5, " notice": 2.5, " noticing": 3.0,
    "看到": 2.7, "看着": 3.5, "看": 1.4, "を見": 2.0, "вид": 2.4, "voir": 1.5, "vedere": 1.5,
}
# verbs of feeling, finding, meeting and spotting
ENCOUNTER = {
    " feel": 1.9, " felt": 1.8, " feels": 1.0, " feeling": 0.9, "感受到": 2.5,
    " find": 0.9, " found": 0.8, " finds": 1.8, " spot": 1.0, " spotted": 1.0,
    " observed": 0.8, " observe": 0.9, " witnessed": 2.0, " witness": 1.5,
    " met": 0.8, " meet": 1.0, " meets": 1.1, " encountered": 1.5, " encounter": 1.5,
    " recognize": 1.0, " recognized": 0.7, " recognizes": 1.1, " realize": 0.8, " realized": 0.6,
    " view": 1.0, " viewed": 1.0,
}
# verbs of imagining, remembering, reading and reporting
THOUGHT = {
    " mind": 1.0, " picture": 0.5, " sight": 0.7, " shows": 0.7, " show": 0.5,
    " imagine": 0.9, " remember": 0.7, " discovered": 0.6, " experienced": 0.6,
    " describes": 0.6, " notes": 0.6, " reports": 0.8, " mentions": 0.7, " read": 0.5,
}
# after these, "of", "to", "at", "about" introduce the thing looked at or thought of
LEAD_IN = {
    " look", " looking", " listen", " listened", " listening", " think", " thinking",
    " talk", " talks", " talked", " sight", " footage", " video", " instance", " example",
    " sense",
}
# after these nouns, "of" introduces a depicted or described thing
DEPICTION = {
    " picture", " image", " video", " footage", " sight", " view", " copy", " description",
    " evidence", " example", " instance", " version", " glimpse",
}
# "see" as a cross-reference ("For details, see ...") is not seeing
XREF_BEFORE = {",", ";", "'s", "(", "."}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.2  # first token of a document
    v = SENSE.get(tok, ENCOUNTER.get(tok, THOUGHT.get(tok, 0.0)))
    if tok == "see" or tok == " see":
        if prev in XREF_BEFORE:
            v = 0.0
    if tok in {" of", " at", " to", " about"} and prev in LEAD_IN:
        v = 2.0
    if tok == " of" and prev in DEPICTION:
        v = max(v, 1.0)
    if tok in {" a", " the"} and (prev in SENSE or prev in ENCOUNTER):
        v = 1.0
    return None, float(v)

"""Layer-1 MLP down-projection component 4404, as a rule-based predictor.

The component is sparse and mostly quiet. Its large activations sit on connective
tokens that open a choice, a pair or a partitive: "or" (and its equivalents in other
languages) after words like "whether", "than", "on"; "of" after a quantifier ("all of",
"most of", "some of"); and a comma or "and" that follows an opener such as "if", "who",
"because", "and", "but", "so". A few other rules add the rarer spikes and a negative
filler case. Everything else predicts 0.
"""

READS = ()

QUANTIFIERS = {"all", "most", "some", "any", "each", "both", "many", "several",
               "either", "none", "much", "one"}
OR_WORDS = {"or", "/or", "oder", "ou", "или", "或", "或者", "ili", "o"}
OR_CONTEXT = {"whether", "than", "with", "if", "on", "more", "one", "to", "of",
              "in", "without", "either", "and", "or"}
CONNECTIVE_OPENERS = {"and", "or", "of", "if", "who", "which", "because", "that",
                      "so", "but", "where"}
ABSTRACT_NOUNS = {"case", "lack", "presence", "absence", "use", "existence"}
PAIR_OPENERS = {"if", "to", "for", "with", "of", "in", "by", "through"}
MIDDLE_DOTS = "·"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    if len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.18  # first token of a document
    prev = prefix.token_strings[-2].strip().lower()
    if cur and set(cur) == {MIDDLE_DOTS}:
        return carry, -1.7  # runs of middle-dot filler
    if cur in OR_WORDS:
        return carry, 1.3 if prev in OR_CONTEXT else 0.12
    if cur == "of":
        if prev in QUANTIFIERS:
            return carry, 1.0
        return carry, -0.6 if prev in ABSTRACT_NOUNS else 0.0
    if cur == "," and prev in CONNECTIVE_OPENERS:
        return carry, 1.0
    if cur == "and" and prev in CONNECTIVE_OPENERS:
        return carry, 1.2
    if cur == "and" and prev in PAIR_OPENERS:
        return carry, 1.6
    if cur == "-" and prev == "из":
        return carry, 3.7  # Russian "из-за" (because of)
    return carry, 0.0

programs.sol:
"""Approximate a mixed syntax-sensitive activation with readable text rules.

URLs, path openings, variable/annotation sigils, namespaces and method receivers
get positive values; code tests and Boolean connectives get negative values.
Indentation and a short preceding text tail distinguish code from prose, TeX,
shell command chains and tables. Smaller cases cover static imports, quantified
"one of", comment openings and runs of middle dots. An isolated UTF-8 C2 lead
byte also gets a positive value. Amplitudes were estimated on training rows.
Unrecognized tokens get a near-zero baseline, not a lexical lookup.
"""
import re

READS = ()

def syntax_activation(token, tail):
    s = token.strip()
    text = tail.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    lead = re.sub(r'^\s*(?:\d+[:\t ]+)?[+\-]?\s*', '', line)
    lead = re.sub(r'^(?:(?:#{1,2}|//|`+)\s*)+', '', lead)
    last = re.search(r'([A-Za-z_][A-Za-z_0-9]*)$', line)
    word = last[1] if last else ''
    indented = not lead and (bool(line) or token[:1].isspace())
    condition = re.match(r'(?:(?:else|})\s+)?(?:if|elif|while|assert)\b', lead)

    # URLs, tests, and Boolean expressions.
    if '://' in s:
        return 1.657 if word in ('http', 'https', 'ftp') else 0.749
    if s in ('if', 'If', 'elif', 'elseif'):
        if s == 'If' and re.search(r'\bDim \w+ As\b', text):
            return -0.666
        if s == 'If' and not indented:
            return 0.032
        if token.startswith('\t'):
            return -0.589
        if s in ('elif', 'elseif'):
            return -0.641
        if indented or word == 'else':
            return -0.666
        if re.search(r'\bcase\b[^:]*:\s*$', line):
            return -0.135
        if re.search(r'(?<![<>=!])=(?!=)|\bfor\b.+\bin\b', lead):
            return -0.135
        if not line or re.search(r'[;{}]\s*$', line):
            return -0.382
        return -0.004
    if s == 'not' and condition:
        return -0.402
    if s in ('&&', '||', 'and', 'or', 'AND', 'OR'):
        if condition or (indented and re.search(
                r'\b(?:if|elif|while)\b[^\n:]*\n[ \t]*$', text)):
            return -1.247
        if s in ('AND', 'OR') and re.search(r'\b(?:WHERE|HAVING)\b', text):
            return -0.867
        if s in ('and', 'or', 'AND', 'OR'):
            if re.match(r'(?:return\b|\w+\s*=)', lead):
                return -0.233
            return 0.006
        if re.search(r'\b(?:cd|echo|mkdir|export|git|python|pytest|npm)\b', line):
            return -0.325
        if re.search(r'(?:===?|!==?|[<>]=?)', line):
            return -0.672
        if '||' in line or re.search(r'\|\s*\d[^A-Za-z]*$', line):
            return 0.001
        if re.search(r'(?:\)|\]|null|nil|NULL|true|false|undefined)\s*$', line):
            return -0.672
        return -0.349 if s == '&&' else -0.08
    # Variable sigils, unlike currency amounts or TeX delimiters.
    if s.endswith('$') and not any(c.isalnum() for c in s):
        code = '->' in text or re.search(
            r'\bforeach\b|<\?php|\$this|\bfunction \w+\(|'
            r'\bmy\s+(?:\\*\$|@)|\$[A-Za-z_]\w*\s*=[^$\n\\]*;', text)
        if '(' in s:
            return 0.637
        if '\\' in s:
            return 1.176 if code else 0.049
        if re.search(r'=>\s*$', line):
            return 0.914
        if re.search(r'(?:=|\breturn|\bas|\becho)\s*$', line):
            return 0.817
        if indented:
            return 0.696
        if code:
            return 0.575
        return 0.049
    # Namespaces and explicit method receivers.
    if s.startswith('::'):
        if s != '::':
            return 0.186
        if word == 'std':
            return 1.473
        if word and word[0].islower() and not line.endswith('.py'):
            return 0.749
        return -0.056
    if s == '->':
        return 0.192 if re.search(r'\$\w+$', line) else 0.001
    if s in ('self', '(self', 'cls', '(cls'):
        if re.search(r'\b(?:def|fn)\s+\w+\s*\([^)]*$', text + s):
            return 1.457
        return -0.039
    # Attribute, annotation, and path prefixes.
    if s == '._':
        return 0.529 if word in ('self', 'this') else 0.095
    if s in ('#[', '#!['):
        return 0.651
    if s in (',@', '(@'):
        return 0.387
    if s == '@':
        return 0.711 if indented else 0.057
    if s.endswith('/') and not any(c.isalnum() for c in s):
        if s in ('/', '//') and tail.endswith(']('):
            return 1.339
        if re.fullmatch(r'''[=(\\]*["']/''', s):
            return 0.757
        if s in ('(/', '`/', '=/', ':/'):
            return 0.633
        if s == '/' and token.startswith(' '):
            if line.endswith(':'):
                return 0.645
            if word in ('cd', 'ls', 'cat', 'find', 'file', 'on', 'of', 'at'):
                return 0.254
