        elif token.isspace():
            value = min(0.4, 0.17 * token.count('\n'))
        elif word.isdigit():
            value = -0.21
        elif word.isalpha():
            if token.startswith(' ') or not (word.isascii() and word.islower()):
                value = -0.20
        elif not any(ch.isalnum() for ch in word):
            value = -0.27
    elif token == ' ' and previous.endswith('  ') and not previous.strip(' \t'):
        value = 0.56 + 0.84 / math.sqrt(position)
    elif position == 1 and token == previous == '\t':
