def language_margin(context, language, alternative='en'):
    words = re.findall(r"[^\W\d_]{2,}", context.lower())[-20:]
    return sum(max(-2., min(2., zipf_frequency(w, language) -
                           zipf_frequency(w, alternative))) for w in words)


def word_signal(word, split, base, context):
