        n = ENGLISH[word]
        if split and n < 10 and base not in ENGLISH:
            return 'split_en', 4.5
        if split:
            return 'number_suffix', 1.25
        if n == 0:
            return 'zero', .25
        if n == 1:
            return 'one', .83
        if n == 2:
            return 'two', 1.5
        if n < 10:
            return 'small', 1.05
        if n == 10:
            return 'ten', .32
        if n < 20:
            return 'teen', .9
        if n < 100:
            return 'tens', .60
        return 'large', .35 if n == 100 else .12
    if word in ORDINALS:
        n = ORDINALS[word]
        return ('ordinal', .6 if n == 2 else .73) if n > 1 else ('first', .06)
    if word in QUANTITIES:
        return word, QUANTITIES[word]
