        lang = NUMBER_WORDS[word]
        if word in {'zweite', 'zweiten', 'dritter', 'dritten', 'vierte', 'vierten'}:
            return 'foreign_ordinal', .4
        if word in {'hundert', 'tausend', 'cent', 'cento', 'cem', 'ciento', 'mil',
                    'mille', 'sto', 'сто'}:
            return 'foreign_scale', .5
