        if zipf_frequency(word, 'en') >= 2.0 and word not in {'dos', 'due'}:
            if language_margin(context, lang) <= 1:
                return 'ambiguous', 0.
        if word in {'ein', 'eine', 'einen', 'einem', 'einer', 'eines', 'een'}:
            return 'indefinite_article', .05
