        if word == 'один' or word.startswith('одн') or word in one_forms:
            value = .7
            if word in {'un', 'uno', 'una', 'une', 'um', 'uma'}:
                langs = ('pt',) if word in {'um', 'uma'} else ('fr', 'es', 'it')
                evidence = max(language_margin(context, l) for l in langs)
                value = .75 if evidence > 0 else .08
