            return 'dos', 5.2 if language_margin(context, 'es', 'pt') > 1 else .05
        if word in {'due', 'tre', 'sei'}:
            margin = language_margin(context, lang)
            if margin <= 1:
                return 'ambiguous', .05
        if word == 'due':
            return 'italian_two', 6.4
        if split and base not in NUMBER_WORDS:
            return 'split_foreign', 5.0
        if split and lang == 'de' and word.endswith(('zig', 'ßig')):
            return 'split_foreign', 5.0
        if split:
            return 'number_suffix', 1.5
        return 'foreign_' + lang, 3.0 if lang != 'fr' else 3.8
