def signal(tail, token, context=''):
    match = WORD_END.search(tail + token)
    word = match.group().lower() if match else ''
    # Han numerals may share a token with a classifier (e.g. "two people").
    if token in {'两', '兩', '双', '雙', '兩個', '两个', '兩个'}:
        return word[-40:], 'han_pair', 1.25
    numeric = []
    for char in token:
        if 'CJK UNIFIED' in unicodedata.name(char, ''):
            try:
                numeric.append(unicodedata.numeric(char))
            except ValueError:
                pass
    if numeric:
        n = numeric[-1]
        if len(token) == 1:
            value = .8 if n < 10 else .65 if n < 100 else .2
            if n == 1:
                value = 1.07
            if n == 0:
                value = .28
            return word[-40:], 'han', value
        value = .4
        if token.endswith(('个', '個', '只')):
            value = .65 if n == 1 else 1.2
        return word[-40:], 'han_compound', value
    split = bool(match and match.start() < len(tail))
    group, value = word_signal(word, split, tail, context)
    return word[-40:], group, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0., 0.)
    _, tail, context, previous, last_number, earlier_number = carry
    token = prefix.token_strings[-1]
    tail, group, value = signal(tail, token, context)
    current = token.strip().lower()
    if current in {'of', 'из'} and last_number > .6:
        value = .85
    if current == 'more' and previous == 'or' and earlier_number > .6:
        value = 1.2
    number = value if group not in {'other_word', 'prefix'} else 0.
    context = '' if token == '<|endoftext|>' else (context + token)[-192:]
    return (doc, tail, context, current, number, last_number), float(value)

