"""Name-expecting detector for layers.1.mlp.down_proj:4408.

This component goes strongly negative on the token just BEFORE a person's name is expected:
the word "by" in "written/directed/founded by", a role label followed by a colon ("Author:",
"Host:"), a title followed by a period ("Dr.", "Prof.Dr", "Mr."), "name" after "my/your/given"
("My name is"), an "I'm" introduction, a letter sign-off ("Best regards," "Yours sincerely"),
and "github.com" before a username. Elsewhere it is near zero.

The program looks only at the current token and the one before it (reset at document
boundaries) and returns a fixed negative value per matched pattern, in rough activation units.
It does not model the small diffuse background, so it explains only part of the variance."""

READS = ()

TITLES = {"Dr", "Prof", "Mr", "Mrs", "Ms", "Sr", "Jr", "Hon", "Rev", "Gen", "Capt", "Col"}
ROLES = {"author", "authors", "editor", "instructor", "host", "teacher", "writer", "artist",
         "director", "bio", "email", "telephone", "contact", "producer", "officer", "photo",
         "photography", "designer", "illustrator", "composer", "singer", "actor", "speaker",
         "founder", "owner", "manager", "developer", "translator", "reviewer", "coach", "by"}
SIGNOFFS = {"regards", "sincerely", "truly", "faithfully", "yours", "Cheers"}
POSSESSIVES = {"my", "your", "his", "her", "given", "first", "full", "real", "personal", "user"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    prev = toks[-2].strip() if len(toks) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1] else ""
    low = prev.lower()
    value = 0.0
    if cur == "." and prev in TITLES:
        value = -1.5
    elif cur == "." and len(prev) == 1 and prev.isupper():
        value = -0.5
    elif cur == ":" and low in ROLES:
        value = -2.0
    elif cur == "by" and (prev.endswith("ed") or prev in {"written", "taken", "given", "known"}):
        value = -0.6
    elif cur == "by":
        value = -0.3
    elif cur.lower() == "name" and low in POSSESSIVES:
        value = -2.0
    elif cur.lower() == "name":
        value = -0.4
    elif cur == "'m" and low == "i":
        value = -0.8
    elif cur in SIGNOFFS:
        value = -1.5
    elif cur == ".com" and "github" in low:
        value = -1.0
    elif cur == ".github":
        value = -1.0
    return carry, value

