    'lesser': -1.5, 'little': -1.5, 'nothing': -1.1,
    'much': -0.55, 'either': -0.5, 'neither': -0.5,
    'inside': -1.0, 'interior': -0.75, 'vicinity': -0.6,
    'right': -1.0, 'north': -0.45, 'northeast': -0.9,
    'youngest': -0.65, 'young': -2.3,
    # Adjectives and verbs taking an 'of' complement.
    'true': -3.5, 'guilty': -1.7, 'died': -1.4,
    'free': -0.9, 'known': -1.8, 'tired': -1.0,
    'required': -0.5, 'typical': -0.4, 'certain': -0.65,
    'intermediate': -1.0, 'search': -0.9, 'well': -0.8,
    'aid': -0.55, 'help': -0.4, 'behalf': -0.35, 'basis': -0.3,
    'independently': -0.7, 'native': -0.85,
}
FROM_COMPLEMENTS = {
    'known': -4.6, 'available': -2.1, 'right': -1.7,
    'free': -0.9, 'originally': -1.1, 'recorded': -0.85,
    'clear': -1.1, 'apparent': -0.8, 'dead': -1.1,
    'died': -0.55, 'seen': -0.3, 'straight': -0.5,
    'plain': -1.2, 'only': -1.4,
