        elif name.endswith('find_all'):
            value = 1.7
        elif name.startswith(('get', 'find')) or name in ('key', 'on'):
            value = 1.3 if single else 1.0
        elif name.startswith(('require', 'read_')):
            value = 0.8
        elif name.startswith(('set', 'add', 'put')):
            value = 0.8 if single else 0.5
        elif name.startswith(('print', 'log')) or name in ('title', 'describe', 'it'):
