"""A surface approximation to a negative separator-punctuation response.

Dashes, colons, arrows, ellipses and spaced opening parentheses are the
main cues. Spacing and rough code/prose context distinguish their uses.
An extra negative response decays with earlier punctuation-only tokens
of the same family in the document. Ordinary tokens stay near zero;
document starts get a small positive estimate. This is not a full parser.
"""
import re

READS = ()
DASHES = frozenset('-‐‑‒–—―−')
ELLIPSIS_MARKS = frozenset('.…⋯・')
CONTROL = re.compile(r'\b(if|for|while|switch|catch|with|except|assert)\s*$')
CODE = re.compile(
    r'[{};=`]|\b(def|class|function|return|const|var|let|import|SELECT|WHERE)\b'
)
NOVELTY = {
    'parenthesis': -0.280,
    'colon': -0.209,
    'dash': -0.591,
    'arrow': -0.223,
    'ellipsis': -0.397,
}


def punctuation_response(token, previous, line):
    """Return punctuation family and its limiting response after repetition."""
    s = token.strip()
    spaced = token[:1].isspace()
    if not s:
        return None, 0.012
    if s.startswith('<|'):
        return None, 0.046
    if s in ('(', '（'):
        value = -0.305
        if s == '（':
            value = -0.253
        elif not spaced:
            value = 0.162
        elif CONTROL.search(line) or CODE.search(line):
            value = 0.002
        elif not line.strip():
            value = 0.129
        elif previous[-1:].isdigit():
            value = -0.428
        elif previous and not previous[-1].isalpha():
            value = -0.069
        return 'parenthesis', value
    if set(s) <= DASHES:
        if any(c != '-' for c in s):
            value = -0.585
        elif len(s) > 2:
            value = -0.215
        elif len(s) == 2:
            value = -0.178
        elif not line.strip() or (not spaced and not previous.strip()):
            value = -0.208
        elif spaced and previous and not previous[-1].isalnum():
            value = 0.125
        else:
            value = -0.273 if spaced else -0.410
        return 'dash', value
    if s in ('->', '-->', '→', '⇒', '⟶', '=>'):
        value = -0.743 if spaced else -0.026
        return 'arrow', -0.059 if s == '=>' else value
    if set(s) <= ELLIPSIS_MARKS and (len(s) > 1 or s == '…'):
        return 'ellipsis', -0.194 if '\n' in token else -0.633
    if s in (':', '：'):
        if spaced:
            value = -0.090
        elif '\n' in token:
            value = -0.281
            if previous[-1:].isdigit():
                value = -0.096
            elif CODE.search(line):
                value = -0.445
        else:
            value = -0.435
            if previous[-1:].isdigit():
                value = -0.260
            elif CODE.search(line):
                value = -0.425
        return 'colon', value
    if ':' in s and not any(c.isalnum() for c in s):
        value = -0.058
        if s == '\":':
            value = -0.336
        elif s == "':":
            value = -0.085
        elif s == '::':
            value = 0.030
        return 'colon', value
    if s == ';':
        return 'colon', 0.060  # Colons and semicolons share a repetition count.
    if s == '~':
        return None, -0.414
    return None, 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != document
    if fresh:
        previous, line, counts = '', '', {}
    else:
        _, previous, line, counts = carry
    token = prefix.token_strings[-1]
    family, value = punctuation_response(token, previous, line)
    if fresh:
        value = 0.257
    elif family:
        value += NOVELTY[family] / (1 + counts.get(family, 0)) ** 0.5
    if family:
        counts[family] = counts.get(family, 0) + 1
    # Only a bounded suffix of the current line is needed for syntax cues.
    line = (line + token).rsplit('\n', 1)[-1][-160:]
    return (document, token, line, counts), value

