"""Connector punctuation: negative on dashes, arrows, ellipses, colons and open brackets.

layers.1.mlp.down_proj:4410 reacts to punctuation that opens an aside, a result or a
list in running prose. Its activation is strongly negative on a token that is itself
a dash ("—", "–", "--", "->", "→", "..."), weaker on a plain hyphen, moderate on a
colon, and weaker still on an open parenthesis written after a space (" ("). Commas,
periods, quotes, words and code-style brackets "(" stay near 0. Within a token, the
magnitude is smaller when the recent text looks like code (brackets, operators,
indentation), which this program reproduces by scaling those predictions by 0.7.

The rule is per token, so it needs no carry state: it reads only the newest token and
the last few tokens of the same document.
"""

import re

READS = ()

LONG_DASHES = {"—", " —", "——", "–", " –", "--", " --", "---", " ---", "-->", " ->", "->",
               "→", " →", "⇒", " ⇒", "…", " …", "……", "...", " ...", "....", " ....", "..",
               "...\n", "...\n\n", "~", "〜"}
HYPHENS = {"-", " -", "‐", "−", " −", "-\n", ".-", ")-"}
COLONS = {":", " :", "：", ":\n", ":\n\n", ":\n\n\n", '":', "):", "：\n\n", ":\\"}
OPEN_PARENS = {" (", "（"}

CODE_CONTEXT = re.compile(r"[{}\[\];=<>_\\()]|\n\s{3,}|\t")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in LONG_DASHES:
        value = -1.0
    elif tok in HYPHENS:
        value = -0.6
    elif tok in COLONS:
        value = -0.5
    elif tok in OPEN_PARENS:
        value = -0.4
    else:
        return carry, 0.0
    # Recent text in the same document: code-like context weakens the response.
    start = len(prefix.document_ids) - 1
    while start > 0 and prefix.document_ids[start - 1] == prefix.document_ids[-1]:
        start -= 1
    recent = "".join(prefix.token_strings[max(start, len(prefix.token_strings) - 13):-1])
    if CODE_CONTEXT.search(recent):
        value *= 0.7
    return carry, value

