"""Chinese 'so/this much/that much', with smaller manner/degree responses.

The largest prediction is for demonstrative degree words ending in me/mo.
A separately tokenized suffix is strong after this/that, not after what/how.
Clause-initial 那么 ('then') is weaker than degree 那么 ('so').
Only a short byte history is retained, including across split UTF-8 characters.
Unmodelled tokens receive a near-zero background.
"""
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
CLAUSE_END = set('，,。.!！?？;；:：\n\r')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_strings[-1].strip()
    previous = before.decode('utf-8', errors='ignore').rstrip()
    carry = (doc, (before + prefix.token_bytes[-1])[-256:])
    if raw.isascii():
        return carry, -0.001
    word = SIMPLIFY.convert(raw).replace('麽', '么')
    last = SIMPLIFY.convert(previous[-1:])
    value = -0.001

    if word == '这么':
        value = 9.3
    elif word == '那么':
        if not previous or previous[-1] in CLAUSE_END:
            value = 2.8 if '如果' in previous[-60:] else 3.9
        else:
            value = 7.7
    elif word in {'这么多', '那么多'}:
        value = 6.5
    elif word in {'就这么', '就那么'}:
        value = 6.9
    elif word == '么':
        if last in {'这', '那'}:
            value = 11.3
        elif last in {'什', '甚'}:
            value = 1.0
        else:
            value = 1.7
    elif word == '般':
        value = 8.0 if last in {'这', '那'} else 1.4
        if last == '一':
            value = 0.0
        elif last == '哪':
            value = 5.0
    elif word == '如此':
        value = 4.8 if previous.endswith('既然') else 2.2
    elif word in {'这样', '那样', '就这样', '就那样'}:
        value = 2.4 if '那' in word or word.startswith('就') else 1.4
    elif word in {'这样的', '那样的'}:
        value = 0.9
    elif raw == 'そんな':  # Japanese 'such'
        value = 1.55
    elif raw == 'あまり':  # Japanese degree/amount adverb
        value = 1.8
    return carry, value

"""Detect the spelling 'for' and several translated prepositions.

This is lexical, not a grammatical sense detector: за and za can also be
word fragments. Reduce English responses at whitespace-only line starts
and after selected governing words. Boost internal Latin za after a
capitalized fragment; recognize Cyrillic з + а across token boundaries.
Double middle dots are another positive spelling. Retain only a short
text tail, reset between documents.
"""
import re
import wordnet

READS = ()

# Common equivalents of 'for'; values describe their different strengths.
FOR_WORDS = {
    'pour': 2.0,
    'para': 1.3,
    'für': 1.35,
    'för': 1.35,
    'voor': 0.9,
    'por': 0.6,
    'per': 0.65,
    'для': 0.96,
    'ل': 1.6,
    'لل': 1.6,
}
# Common heads taking a 'for' complement; WordNet handles inflections.
LOW_FOR = {'look', 'wait', 'allow'}
SELECT_FOR = {
    'ask', 'search', 'account', 'prepare', 'ready', 'responsible',
    'know', 'grateful',
}
PURPOSE_FOR = {
    'need', 'necessary', 'essential', 'suitable', 'reason', 'design',
    'solve',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    boundary = not before or not before[-1].isalnum()
    separated = token.startswith(' ') or boundary
    value = 0.0

    if word.lower() == 'for':
        if word == 'For':
            value = 0.9
        elif word == 'FOR':
            value = 1.55
        elif token == ' for':
            value = 1.6
            if before and not before.rsplit('\n', 1)[-1].strip():
                value = -0.1
            else:
                match = re.search(r'([A-Za-z]+)\s*$', before)
                if match:
                    previous = match[1].lower()
                    forms = {previous, *wordnet.base_forms(previous)}
                    if forms & LOW_FOR:
                        value = 0.5
                    elif forms & SELECT_FOR:
                        value = 0.85
                    elif forms & PURPOSE_FOR:
                        value = 1.1
        elif before.endswith('('):
            value = 1.75
        else:
            value = 0.65 if boundary else 0.25
