        if before.endswith('-'):
            value = 3.2  # The compound preposition из-за.
        elif word == 'За':
            value = 11.5 if separated else 8.0
        else:
            value = 8.0 if separated else 1.0
    elif token == 'а' and before.endswith('з'):
        value = 6.2
    elif word.lower() == 'za':
        value = (9.3 if word == 'za' else 4.2) if separated else 0.0
        name = re.search(r'([A-Za-z]+)$', before)
        if not separated and name and name[1][0].isupper():
            value = 6.0
    elif separated and word.lower() in FOR_WORDS:
        value = FOR_WORDS[word.lower()]
        if word == 'Pour':
            value = 1.4
    elif token in (' over', ' Over'):
        value = 0.77
    elif token == '··':
        value = 1.19

    return (doc, (before + token)[-96:]), value

"""Approximate an early orthographic-fragment response.

Use a positive document-opening baseline, especially for capitalized text.
Inside words, recognize Greek inflection letters, Japanese vowel-length marks,
fragmented capitals, and the Thai cancellation mark.  Their strength depends on
how many token pieces already spell the word.  These orthographic averages
leave substantial token-specific behavior unexplained.
"""
from functools import lru_cache
import unicodedata
import regex

READS = ()
GREEK = regex.compile(r'(?:\p{Greek}|\p{M})+$')
KANA = regex.compile(r'[\p{Katakana}ー]+$')
CAPITALS = regex.compile(r'[\p{Lu}.\x00]+$')
THAI = regex.compile(r'\p{Thai}+$')
# Common Greek noun/adverb endings, completed by final sigma.
SIGMA_ENDINGS = {'α': -0.50, 'ο': -0.41, 'ω': -0.42,
                 'η': -0.18, 'ε': -0.19}


@lru_cache(maxsize=32768)
def token_kind(raw):
    text = raw.decode('utf-8', 'replace')
    normalized = unicodedata.normalize('NFKC', text)
    plain = ''.join(c for c in unicodedata.normalize('NFD', normalized)
                    if unicodedata.category(c) != 'Mn')
    kind = ''
    if plain and GREEK.fullmatch(plain):
        kind = ('sigma' if plain == 'ς' else
                'vowel' if len(plain) == 1 and plain in 'αεηιουω' else 'greek')
    elif text == 'ー':
        kind = 'length'
    elif text.startswith('ー') and '\ufffd' in text:
        kind = 'partial_length'
    elif (normalized and not normalized[0].isspace()
          and normalized.strip('.').isalpha()
          and normalized.strip('.').isupper()):
        kind = 'capitals'
    elif text == '์':
        kind = 'cancellation'
    return normalized, kind


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    history = [] if first else carry[1]
    raw = prefix.token_bytes[-1]
    text, kind = token_kind(raw)
    value = 0.0
    if first:
        if text[:1].isspace():
            value = 0.10
        elif text.istitle() or text.isupper():
            value = 0.38
        else:
            value = 0.15
    elif kind:
        pattern = (GREEK if kind in ('sigma', 'vowel', 'greek') else
                   KANA if kind in ('length', 'partial_length') else
                   THAI if kind == 'cancellation' else CAPITALS)
        match = pattern.search(b''.join(history).decode('utf-8', 'replace'))
        word = match[0] if match else ''
        remaining = len(word.encode('utf-8'))
        pieces = 0
        for piece in reversed(history):
            if remaining <= 0:
                break
            remaining -= len(piece)
            pieces += 1
        if kind == 'sigma' and pieces >= 3:
            last_letter = ''.join(
                c for c in unicodedata.normalize('NFD', word)
                if unicodedata.category(c) != 'Mn')[-1:]
            value = SIGMA_ENDINGS.get(last_letter, -0.25)
        elif kind == 'vowel' and pieces >= 2:
            value = -0.12 if pieces < 7 else -0.07
        elif kind == 'greek' and pieces >= 3:
            value = -0.02
        elif kind == 'length':
            value = (-0.70 if pieces == 3 else
                     -0.30 if pieces >= 2 else -0.06)
        elif kind == 'partial_length' and pieces >= 2:
            value = -0.15
        elif kind == 'cancellation':
            value = -0.60 if word.endswith('ร') else -0.06
        elif kind == 'capitals' and pieces >= 2:
            if word.count('.') >= 2 and pieces >= 3:
                value = -0.35
            elif text.strip('.') in ('A', 'E', 'I', 'O', 'U') and pieces <= 5:
                value = -0.13 if pieces >= 3 else -0.06
            elif text.endswith('S') and pieces <= 3:
                value = -0.06
            else:
                value = -0.03
    return (document, (history + [raw])[-16:]), value

programs.haiku:
"""Explains layers.1.mlp.down_proj component 4413 (a small, mostly quiet direction).

What it does, in plain terms:
- It is strongly active on the FIRST token of each document (the token right after a
  document break, which has no earlier context). There it is positive for a word that
  starts with a capital letter (e.g. "Person", "Users", "Test"), mildly positive for other
  ordinary words and punctuation, and slightly negative for code-like identifiers
  (`def`, `const`, `_model`, `.py`).
- Later in a document it is near zero, except for a few characters: it is positive on the
  middle dot "·" (interpunct) and negative on Greek final sigma "ς" and on the katakana
  prolonged-sound mark "ー".

The rules below are a readable approximation: they capture the largest pieces of the
variance, not the full token-by-token pattern, which is diffuse.
"""

READS = ()

MIDDLE_DOT = "·"
NEGATIVE_CHARS = {"ς": -0.2, "ー": -0.25}
CODE_CHARS = set("_().{}[];=<>")


def _is_capitalized(text):
    word = text.strip()
    return bool(word) and word[0].isupper()


def _is_code_like(text):
    return any(c in CODE_CHARS for c in text)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids
    first_in_document = len(doc) == 1 or doc[-2] != doc[-1]
    if first_in_document:
        if _is_capitalized(text):
            return carry, 0.35
        if _is_code_like(text):
            return carry, -0.05
        return carry, 0.12
    if MIDDLE_DOT in text:
        return carry, 0.5
    return carry, NEGATIVE_CHARS.get(text.strip(), 0.0)
